void candidate() {

  const int INF = 1000000000;
  List<List<int>> graph = [
    [0,   3,   INF, 5],
    [2,   0,   INF, 4],
    [INF, 1,   0,   INF],
    [INF, INF, 2,   0]
  ];

  int n = graph.length;

  List<List<int>> dist = List.generate(n, (i) => List<int>.from(graph[i]));

  for (int k = 0; k < n; k++) {
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < n; j++) {
        if (dist[i][k] < INF && dist[k][j] < INF) {
          if (dist[i][j] > dist[i][k] + dist[k][j]) {
            dist[i][j] = dist[i][k] + dist[k][j];
          }
        }
      }
    }
  }

  print('All-pairs shortest path matrix:');
  for (int i = 0; i < n; i++) {
    String row = '';
    for (int j = 0; j < n; j++) {
      if (dist[i][j] == INF) {
        row += 'INF'.padLeft(5);
      } else {
        row += dist[i][j].toString().padLeft(5);
      }
    }
    print(row);
  }
}

