void candidate() {

  List<int> coins = [1, 2, 5];
  int amount = 11;


  List<int> dp = List.filled(amount + 1, amount + 1);
  dp[0] = 0;

  for (int i = 1; i <= amount; i++) {
    for (int coin in coins) {
      if (i - coin >= 0) {
        dp[i] = dp[i] < dp[i - coin] + 1 ? dp[i] : dp[i - coin] + 1;
      }
    }
  }

  if (dp[amount] > amount) {
    print('It is not possible to make $amount with coins $coins');
  } else {
    print('Minimum coins needed to make $amount with coins $coins: ${dp[amount]}');
  }
}

