@pragma('vm:never-inline')
@pragma('vm:entry-point')
void candidate() {



  List<List<int>> dist = [
    [0, 1, 2, 3],
    [1, 0, 4, 6],
    [2, 4, 0, 5],
    [3, 6, 5, 0],
  ];

  int n = dist.length;
  List<int> cities = List.generate(n, (i) => i);

  int minCost = 1 << 30;
  List<int> bestPath = [];

  void permute(List<int> arr, int l, int r) {
    if (l == r) {

      int cost = 0;
      int prev = 0;
      for (int city in arr) {
        cost += dist[prev][city];
        prev = city;
      }
      cost += dist[prev][0]; 

      if (cost < minCost) {
        minCost = cost;
        bestPath = [0, ...arr, 0];
      }
    } else {
      for (int i = l; i <= r; i++) {
        arr = List.from(arr); 
        int tmp = arr[l];
        arr[l] = arr[i];
        arr[i] = tmp;
        permute(arr, l + 1, r);
      }
    }
  }

  List<int> permCities = List.generate(n - 1, (i) => i + 1);
  permute(permCities, 0, permCities.length - 1);

  print('Minimum cost: $minCost');
  print('Best path: ${bestPath.join(" -> ")}');
}

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void candidate() {
  const int n = 8; 

  bool isSafe(List<int> queens, int row, int col) {
    for (int i = 0; i < row; i++) {
      int qCol = queens[i];
      if (qCol == col || 
          (i - row).abs() == (qCol - col).abs()) 
        return false;
    }
    return true;
  }

  void solve(int row, List<int> queens, List<List<int>> solutions) {
    if (row == n) {
      solutions.add(List.from(queens));
      return;
    }
    for (int col = 0; col < n; col++) {
      if (isSafe(queens, row, col)) {
        queens[row] = col;
        solve(row + 1, queens, solutions);
      }
    }
  }

  void printBoard(List<int> queens) {
    for (int i = 0; i < n; i++) {
      String row = List.generate(n, (j) => queens[i] == j ? 'Q' : '.').join(' ');
      print(row);
    }
    print('');
  }

  List<List<int>> solutions = [];
  solve(0, List.filled(n, -1), solutions);

  print('Total solutions for $n-Queens: ${solutions.length}\n');
  for (int i = 0; i < solutions.length; i++) {
    print('Solution ${i + 1}:');
    printBoard(solutions[i]);
