    Point(0, 3),
    Point(2, 2),
    Point(1, 1),
    Point(2, 1),
    Point(3, 0),
    Point(0, 0),
    Point(3, 3),
  ];

  if (points.length <= 1) {
    print('Convex hull: $points');
    return;
  }

  points.sort((a, b) {
    if (a.y != b.y) return a.y - b.y;
    return a.x - b.x;
  });
  Point p0 = points[0];

  points = [p0] +
      points.sublist(1)
        ..sort((a, b) {
          int cp = cross(p0, a, b);
          if (cp == 0) {

            return dist2(p0, a) - dist2(p0, b);
          }
          return -cp; 
        });

  List<Point> hull = [];
  for (var p in points) {
    while (hull.length >= 2 &&
        cross(hull[hull.length - 2], hull[hull.length - 1], p) <= 0) {
      hull.removeLast();
    }
    hull.add(p);
  }

  print('Convex hull:');
  for (var p in hull) {
    print(p);
  }
}

