  ];

  List<List<Point<double>>> triangulate(List<Point<double>> poly) {
    if (poly.length < 3) return [];
    List<int> V = List.generate(poly.length, (i) => i);

    bool isCCW(List<Point<double>> pts) {
      double area = 0;
      for (int i = 0; i < pts.length; i++) {
        int j = (i + 1) % pts.length;
        area += (pts[j].x - pts[i].x) * (pts[j].y + pts[i].y);
      }
      return area < 0;
    }

    bool isConvex(Point<double> prev, Point<double> curr, Point<double> next) {
      double cross = (curr.x - prev.x) * (next.y - curr.y) -
          (curr.y - prev.y) * (next.x - curr.x);
      return cross < 0; 
    }

    bool pointInTriangle(Point<double> p, Point<double> a, Point<double> b, Point<double> c) {
      double area = (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
      double s = ((a.y - c.y) * (p.x - c.x) + (c.x - a.x) * (p.y - c.y)) / area;
      double t = ((c.y - b.y) * (p.x - c.x) + (b.x - c.x) * (p.y - c.y)) / area;
      double u = 1 - s - t;
      return s > 0 && t > 0 && u > 0;
    }

    if (!isCCW(poly)) {
      poly = poly.reversed.toList();
    }

    List<List<Point<double>>> triangles = [];
    int n = poly.length;
    int count = 0; 

    while (V.length > 3 && count < 1000) {
      bool earFound = false;
      for (int i = 0; i < V.length; i++) {
        int prev = V[(i - 1 + V.length) % V.length];
        int curr = V[i];
        int next = V[(i + 1) % V.length];

        Point<double> pPrev = poly[prev];
        Point<double> pCurr = poly[curr];
        Point<double> pNext = poly[next];

        if (isConvex(pPrev, pCurr, pNext)) {

          bool hasPointInside = false;
          for (int j = 0; j < V.length; j++) {
            if (j == (i - 1 + V.length) % V.length ||
                j == i ||
                j == (i + 1) % V.length) continue;
            if (pointInTriangle(poly[V[j]], pPrev, pCurr, pNext)) {
              hasPointInside = true;
              break;
            }
          }
          if (!hasPointInside) {
            triangles.add([pPrev, pCurr, pNext]);
            V.removeAt(i);
            earFound = true;
            break;
          }
        }
      }
      if (!earFound) break; 
      count++;
    }
    if (V.length == 3) {
      triangles.add([poly[V[0]], poly[V[1]], poly[V[2]]]);
    }
    return triangles;
  }

  var triangles = triangulate(polygon);

  print('Triangulation result:');
  for (var tri in triangles) {
    print(tri.map((p) => '(${p.x}, ${p.y})').join(' - '));
  }
}

