class KDNode {
  List<num> point;
  KDNode? left;
  KDNode? right;
  int axis;

  KDNode(this.point, this.axis, {this.left, this.right});
}

KDNode? buildKDTree(List<List<num>> points, int depth) {
  if (points.isEmpty) return null;

  int k = points[0].length;
  int axis = depth % k;

  points.sort((a, b) => a[axis].compareTo(b[axis]));

  int median = points.length ~/ 2;
  List<num> medianPoint = points[median];

  var left = buildKDTree(points.sublist(0, median), depth + 1);
  var right = buildKDTree(points.sublist(median + 1), depth + 1);

  return KDNode(medianPoint, axis, left: left, right: right);
}

void printKDTree(KDNode? node, int depth) {
  if (node == null) return;
  String indent = '  ' * depth;
  print('$indent${node.point} (axis=${node.axis})');
  printKDTree(node.left, depth + 1);
  printKDTree(node.right, depth + 1);
}

import 'dart:math';

class Point {
  final double x, y;
  Point(this.x, this.y);

  @override
  String toString() => '($x, $y)';
}

class Rect {
  final double x, y, w, h; 
  Rect(this.x, this.y, this.w, this.h);

  bool contains(Point p) =>
      (p.x >= x - w) &&
      (p.x <= x + w) &&
      (p.y >= y - h) &&
      (p.y <= y + h);

  bool intersects(Rect range) =>
      !(range.x - range.w > x + w ||
        range.x + range.w < x - w ||
        range.y - range.h > y + h ||
        range.y + range.h < y - h);

  @override
  String toString() => 'Rect(center: $x, $y, hw: $w, hh: $h)';
}

class QuadTree {
  final Rect boundary;
  final int capacity;
  final List<Point> points = [];
  bool divided = false;
  QuadTree? northeast, northwest, southeast, southwest;

  QuadTree(this.boundary, [this.capacity = 4]);

  bool insert(Point p) {
    if (!boundary.contains(p)) return false;
    if (points.length < capacity) {
      points.add(p);
      return true;
    }
    if (!divided) subdivide();
    return (northeast!.insert(p) ||
        northwest!.insert(p) ||
        southeast!.insert(p) ||
        southwest!.insert(p));
  }

  void subdivide() {
    double x = boundary.x, y = boundary.y, w = boundary.w / 2, h = boundary.h / 2;
    northeast = QuadTree(Rect(x + w, y - h, w, h), capacity);
    northwest = QuadTree(Rect(x - w, y - h, w, h), capacity);
    southeast = QuadTree(Rect(x + w, y + h, w, h), capacity);
    southwest = QuadTree(Rect(x - w, y + h, w, h), capacity);
    divided = true;
  }

  void query(Rect range, List<Point> found) {
    if (!boundary.intersects(range)) return;
    for (var p in points) {
      if (range.contains(p)) found.add(p);
    }
    if (divided) {
      northeast!.query(range, found);
      northwest!.query(range, found);
      southeast!.query(range, found);
      southwest!.query(range, found);
    }
  }

  void printTree([int depth = 0]) {
    String indent = '  ' * depth;
    print('$indent$boundary: ${points.length} points');
    if (divided) {
      northeast!.printTree(depth + 1);
      northwest!.printTree(depth + 1);
      southeast!.printTree(depth + 1);
      southwest!.printTree(depth + 1);
    }
  }
}

