  List<List<T>> combinations<T>(List<T> elements, int k) {
    List<List<T>> result = [];
    void combine(int start, List<T> current) {
      if (current.length == k) {
        result.add(List<T>.from(current));
        return;
      }
      for (int i = start; i < elements.length; i++) {
        current.add(elements[i]);
        combine(i + 1, current);
        current.removeLast();
      }
    }
    combine(0, []);
    return result;
  }

  List<List<int>> combs = combinations(items, k);
  print('Combinations of $items taken $k at a time:');
  for (var c in combs) {
