void candidate() {

  final data = [
    [1.0, 2.0],
    [1.5, 1.8],
    [5.0, 8.0],
    [8.0, 8.0],
    [1.0, 0.6],
    [9.0, 11.0],
    [8.0, 2.0],
    [10.0, 2.0],
    [9.0, 3.0],
  ];

  List<List<int>> clusters = List.generate(data.length, (i) => [i]);

  double dist(int i, int j) {
    double sum = 0.0;
    for (int d = 0; d < data[i].length; d++) {
      sum += pow(data[i][d] - data[j][d], 2);
    }
    return sqrt(sum);
  }

  double clusterDist(List<int> a, List<int> b) {
    double minDist = double.infinity;
    for (var i in a) {
      for (var j in b) {
        if (i != j) {
          double d = dist(i, j);
          if (d < minDist) minDist = d;
        }
      }
    }
    return minDist;
  }

  print('Initial clusters:');
  print(clusters);

  while (clusters.length > 1) {
    double minDistance = double.infinity;
    int mergeA = -1, mergeB = -1;

    for (int i = 0; i < clusters.length; i++) {
      for (int j = i + 1; j < clusters.length; j++) {
        double d = clusterDist(clusters[i], clusters[j]);
        if (d < minDistance) {
          minDistance = d;
          mergeA = i;
          mergeB = j;
        }
      }
    }

    if (mergeA != -1 && mergeB != -1) {
      clusters[mergeA] = [...clusters[mergeA], ...clusters[mergeB]];
      clusters.removeAt(mergeB);
      print('Merged clusters $mergeA and $mergeB at distance $minDistance');
      print('Clusters: $clusters');
    } else {
      break;
    }
  }

  print('\nFinal cluster:');
  print(clusters);
}

