import 'dart:math';

class Complex {
  final double re;
  final double im;

  const Complex(this.re, this.im);

  Complex operator +(Complex other) => Complex(re + other.re, im + other.im);

  Complex operator -(Complex other) => Complex(re - other.re, im - other.im);

  Complex operator *(Complex other) =>
      Complex(re * other.re - im * other.im, re * other.im + im * other.re);

  Complex operator /(Complex other) {
    final denom = other.re * other.re + other.im * other.im;
    if (denom == 0) throw ArgumentError('Division by zero');
    return Complex(
      (re * other.re + im * other.im) / denom,
      (im * other.re - re * other.im) / denom,
    );
  }

  double abs() => sqrt(re * re + im * im);

  double arg() => atan2(im, re);

  Complex conjugate() => Complex(re, -im);

  @override
  String toString() {
    String sign = im >= 0 ? '+' : '-';
    return '${re.toStringAsFixed(2)} $sign ${im.abs().toStringAsFixed(2)}i';
  }
}

