    printTree(node.left, depth + 1);
    print('Depth $depth: ${node.point}');
    printTree(node.right, depth + 1);
  }

  print('Constructed k-d tree:');
  printTree(root, 0);
}

import 'dart:math';

class SkipListNode {
  int value;
  List<SkipListNode?> forward;

  SkipListNode(this.value, int level) : forward = List<SkipListNode?>.filled(level + 1, null);
}

class SkipList {
  static const double probability = 0.5;
  static const int maxLevel = 16;

  SkipListNode head;
  int level;
  Random random;

  SkipList()
      : head = SkipListNode(-1, maxLevel),
        level = 0,
        random = Random(0);

  int _randomLevel() {
    int lvl = 0;
    while (lvl < maxLevel && random.nextDouble() < probability) {
      lvl++;
    }
    return lvl;
  }

  void insert(int value) {
    List<SkipListNode?> update = List<SkipListNode?>.filled(maxLevel + 1, null);
    SkipListNode? current = head;

    for (int i = level; i >= 0; i--) {
      while (current!.forward[i] != null && current.forward[i]!.value < value) {
        current = current.forward[i];
      }
      update[i] = current;
    }

    current = current!.forward[0];

    if (current == null || current.value != value) {
      int newLevel = _randomLevel();

      if (newLevel > level) {
        for (int i = level + 1; i <= newLevel; i++) {
          update[i] = head;
        }
        level = newLevel;
      }

      SkipListNode newNode = SkipListNode(value, newLevel);

      for (int i = 0; i <= newLevel; i++) {
        newNode.forward[i] = update[i]!.forward[i];
        update[i]!.forward[i] = newNode;
      }
    }
  }

  bool search(int value) {
    SkipListNode? current = head;

    for (int i = level; i >= 0; i--) {
      while (current!.forward[i] != null && current.forward[i]!.value < value) {
        current = current.forward[i];
      }
    }

    current = current!.forward[0];
    return current != null && current.value == value;
  }

  void delete(int value) {
    List<SkipListNode?> update = List<SkipListNode?>.filled(maxLevel + 1, null);
    SkipListNode? current = head;

    for (int i = level; i >= 0; i--) {
      while (current!.forward[i] != null && current.forward[i]!.value < value) {
        current = current.forward[i];
      }
      update[i] = current;
    }

    current = current!.forward[0];

    if (current != null && current.value == value) {
      for (int i = 0; i <= level; i++) {
        if (update[i]!.forward[i] != current) break;
        update[i]!.forward[i] = current.forward[i];
      }

      while (level > 0 && head.forward[level] == null) {
        level--;
      }
    }
  }

