    if (board[2] == player && board[4] == player && board[6] == player) return true;
    return false;
  }

  bool isFull(List<String> board) {
    return !board.contains(' ');
  }

  List<int> availableMoves(List<String> board) {
    List<int> moves = [];
    for (int i = 0; i < board.length; i++) {
      if (board[i] == ' ') moves.add(i);
    }
    return moves;
  }



  int alphaBeta(List<String> board, int depth, int alpha, int beta, bool isMaximizing, String maxPlayer, String minPlayer) {
    if (hasWon(board, maxPlayer)) return 10 - depth; 
    if (hasWon(board, minPlayer)) return depth - 10; 
    if (isFull(board)) return 0; 

    if (isMaximizing) {
      int maxEval = -999999; 
      for (int move in availableMoves(board)) {
        board[move] = maxPlayer;
        int eval = alphaBeta(board, depth + 1, alpha, beta, false, maxPlayer, minPlayer);
        board[move] = ' '; 
        maxEval = max(maxEval, eval);
        alpha = max(alpha, eval);
        if (beta <= alpha) break; 
      }
      return maxEval;
    } else {
      int minEval = 999999; 
      for (int move in availableMoves(board)) {
        board[move] = minPlayer;
        int eval = alphaBeta(board, depth + 1, alpha, beta, true, maxPlayer, minPlayer);
        board[move] = ' '; 
        minEval = min(minEval, eval);
        beta = min(beta, eval);
        if (beta <= alpha) break; 
      }
      return minEval;
    }
  }


  int findBestMove(List<String> board, bool isMaximizing, String maxPlayer, String minPlayer) {
    int bestScore = isMaximizing ? -999999 : 999999;
    int bestMove = -1;

    for (int move in availableMoves(board)) {
      String player = isMaximizing ? maxPlayer : minPlayer;
      board[move] = player;
      int score = alphaBeta(board, 0, -999999, 999999, !isMaximizing, maxPlayer, minPlayer);
      board[move] = ' '; 

      if (isMaximizing) {
        if (score > bestScore) {
          bestScore = score;
          bestMove = move;
        }
      } else {
        if (score < bestScore) {
          bestScore = score;
          bestMove = move;
        }
      }
    }
    return bestMove;
  }

