class ReifiedList<T> {
  late Type _elementType;
  final List<T> _list = [];

  ReifiedList(Type elementType) {
    _elementType = elementType;
  }

  void add(T item) {
    if (item.runtimeType != _elementType) {
      throw ArgumentError(
          'Item type ${item.runtimeType} does not match expected type $_elementType');
    }
    _list.add(item);
  }

  T get(int index) {
    return _list[index];
  }

  int get length => _list.length;
}

