bool isMatch(String s, String p) {

  final m = s.length;
  final n = p.length;
  final dp = List.generate(m + 1, (_) => List<bool>.filled(n + 1, false));

  dp[0][0] = true; 

  for (int j = 1; j <= n; j++) {
    if (p[j - 1] == '*') {
      dp[0][j] = dp[0][j - 1];
    }
  }

  for (int i = 1; i <= m; i++) {
    for (int j = 1; j <= n; j++) {
      if (p[j - 1] == '*') {

        dp[i][j] = dp[i][j - 1] || dp[i - 1][j];
      } else if (p[j - 1] == '?' || p[j - 1] == s[i - 1]) {
        dp[i][j] = dp[i - 1][j - 1];
      }
    }
  }

  return dp[m][n];
}

