@pragma('vm:never-inline')
@pragma('vm:entry-point')
void candidate() {

  final weights = [2, 1, 3, 2];
  final values = [12, 10, 20, 15];
  final capacity = 5;
  final n = weights.length;

  final dp = List.generate(n + 1, (_) => List.filled(capacity + 1, 0));

  for (int i = 1; i <= n; i++) {
    for (int w = 0; w <= capacity; w++) {

      if (weights[i - 1] > w) {
        dp[i][w] = dp[i - 1][w];
      } else {

        dp[i][w] = dp[i - 1][w] > (dp[i - 1][w - weights[i - 1]] + values[i - 1])
            ? dp[i - 1][w]
            : dp[i - 1][w - weights[i - 1]] + values[i - 1];
      }
    }
  }

  final selectedItems = <int>[];
  int w = capacity;
  for (int i = n; i > 0 && w > 0; i--) {
    if (dp[i][w] != dp[i - 1][w]) {
      selectedItems.add(i - 1);
      w -= weights[i - 1];
    }
  }

  print('Items: ${List.generate(n, (i) => 'Item${i + 1}')}');
  print('Weights: $weights');
  print('Values: $values');
  print('Knapsack capacity: $capacity');
  print('');
  print('DP Table:');
  for (int i = 0; i <= n; i++) {
    String row = '';
    for (int j = 0; j <= capacity; j++) {
      row += '${dp[i][j].toString().padLeft(3)} ';
    }
    print(row);
  }
  print('');
  print('Maximum value: ${dp[n][capacity]}');
  print('Selected items (0-indexed): ${selectedItems.reversed.toList()}');

  int totalWeight = 0;
  int totalValue = 0;
  for (int idx in selectedItems) {
    totalWeight += weights[idx];
    totalValue += values[idx];
  }
  print('Total weight: $totalWeight');
  print('Total value: $totalValue');
}

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void candidate() {

  var board = [
    [5, 3, 0, 0, 7, 0, 0, 0, 0],
    [6, 0, 0, 1, 9, 5, 0, 0, 0],
    [0, 9, 8, 0, 0, 0, 0, 6, 0],
    [8, 0, 0, 0, 6, 0, 0, 0, 3],
    [4, 0, 0, 8, 0, 3, 0, 0, 1],
    [7, 0, 0, 0, 2, 0, 0, 0, 6],
    [0, 6, 0, 0, 0, 0, 2, 8, 0],
    [0, 0, 0, 4, 1, 9, 0, 0, 5],
    [0, 0, 0, 0, 8, 0, 0, 7, 9]
  ];

  print('Original Sudoku puzzle:');
  for (var row in board) {
    print(row.map((cell) => cell == 0 ? '.' : cell.toString()).join(' '));
  }
  print('');

  bool isValid(List<List<int>> board, int row, int col, int num) {

    for (int x = 0; x < 9; x++) {
      if (board[row][x] == num) {
        return false;
      }
    }

    for (int x = 0; x < 9; x++) {
      if (board[x][col] == num) {
        return false;
      }
    }

    int startRow = row - row % 3;
    int startCol = col - col % 3;
    for (int i = 0; i < 3; i++) {
      for (int j = 0; j < 3; j++) {
        if (board[i + startRow][j + startCol] == num) {
          return false;
        }
      }
    }

    return true;
  }

  List<int>? findEmpty(List<List<int>> board) {
    for (int i = 0; i < 9; i++) {
      for (int j = 0; j < 9; j++) {
        if (board[i][j] == 0) {
          return [i, j];
        }
      }
    }
    return null;
  }

  bool solve(List<List<int>> board) {
    var empty = findEmpty(board);
    if (empty == null) {
      return true; 
    }

    int row = empty[0];
    int col = empty[1];

    for (int num = 1; num <= 9; num++) {
      if (isValid(board, row, col, num)) {
        board[row][col] = num;

        if (solve(board)) {
          return true;
        }

        board[row][col] = 0;
      }
    }

    return false;
  }

  if (solve(board)) {
    print('Solved Sudoku puzzle:');
    for (var row in board) {
      print(row.join(' '));
    }
  } else {
    print('No solution exists for this Sudoku puzzle.');
  }
}

