  List<List<int>> generatePermutations(List<int> nums) {
    List<List<int>> result = [];
    List<int> currentPermutation = [];
    List<bool> used = List.filled(nums.length, false);

    void backtrack() {

      if (currentPermutation.length == nums.length) {
        result.add(List.from(currentPermutation));
        return;
      }

      for (int i = 0; i < nums.length; i++) {
        if (used[i]) continue;

        currentPermutation.add(nums[i]);
        used[i] = true;

        backtrack();

        currentPermutation.removeLast();
        used[i] = false;
      }
    }

    backtrack();
    return result;
  }

  print('Permutations of $nums1:');
  List<List<int>> perms1 = generatePermutations(nums1);
  for (var perm in perms1) {
    print(perm);
