sealed class Shape {}

class Circle extends Shape {
  final double radius;
  Circle({required this.radius});
}

class Rectangle extends Shape {
  final double width;
  final double height;
  Rectangle({required this.width, required this.height});
}

class Square extends Shape {
  final double side;
  Square({required this.side});
}

class Triangle extends Shape {
  final double base;
  final double height;
  Triangle({required this.base, required this.height});
}

String describeShape(Shape shape) {
  return switch (shape) {
    Circle(radius: var r) => 'Circle with radius $r',
    Rectangle(width: var w, height: var h) => 'Rectangle ${w}x$h',
    Square(side: var s) => 'Square with side $s',
    Triangle(base: var b, height: var h) => 'Triangle with base $b and height $h',
  };
}

double calculateArea(Shape shape) {
  return switch (shape) {
    Circle(radius: var r) => 3.14159 * r * r,
    Rectangle(width: var w, height: var h) => w * h,
    Square(side: var s) => s * s,
    Triangle(base: var b, height: var h) => 0.5 * b * h,
  };
}

double calculatePerimeter(Shape shape) {
  return switch (shape) {
    Circle(radius: var r) => 2 * 3.14159 * r,
    Rectangle(width: var w, height: var h) => 2 * (w + h),
    Square(side: var s) => 4 * s,
    Triangle(base: var b, height: var h) => b + 2 * ((b/2) * (b/2) + h * h).sqrt(),
  };
}

sealed class Expression {}

class Number extends Expression {
  final int value;
  Number(this.value);
}

class Add extends Expression {
  final Expression left;
  final Expression right;
  Add(this.left, this.right);
}

class Multiply extends Expression {
  final Expression left;
  final Expression right;
  Multiply(this.left, this.right);
}

class Subtract extends Expression {
  final Expression left;
  final Expression right;
  Subtract(this.left, this.right);
}

int evaluate(Expression expr) {
  return switch (expr) {
    Number(value: var v) => v,
    Add(left: var l, right: var r) => evaluate(l) + evaluate(r),
    Multiply(left: var l, right: var r) => evaluate(l) * evaluate(r),
    Subtract(left: var l, right: var r) => evaluate(l) - evaluate(r),
  };
}

String expressionToString(Expression expr) {
  return switch (expr) {
    Number(value: var v) => v.toString(),
    Add(left: var l, right: var r) => '(${expressionToString(l)} + ${expressionToString(r)})',
    Multiply(left: var l, right: var r) => '(${expressionToString(l)} * ${expressionToString(r)})',
    Subtract(left: var l, right: var r) => '(${expressionToString(l)} - ${expressionToString(r)})',
  };
}

sealed class Result<T> {}

class Success<T> extends Result<T> {
  final T value;
  Success(this.value);
}

class Failure<T> extends Result<T> {
  final String error;
  Failure(this.error);
}

void handleResult(Result<int> result) {
  switch (result) {
    case Success(value: var v):
      print('Success! Got value: $v');
    case Failure(error: var e):
      print('Failed with error: $e');
  }
}

