@pragma('vm:never-inline')
@pragma('vm:entry-point')
void candidate(List<String> args) {



  final Map<String, Map<String, double>> ratings = {
    'User1': {'ItemA': 5, 'ItemB': 3, 'ItemC': 2},
    'User2': {'ItemA': 4, 'ItemB': 2, 'ItemD': 3},
    'User3': {'ItemA': 2, 'ItemC': 5, 'ItemD': 3},
    'User4': {'ItemB': 5, 'ItemC': 3},
    'User5': {'ItemA': 4, 'ItemB': 4, 'ItemC': 1, 'ItemD': 5},
  };



  if (args.isEmpty) {
    print('Usage: dart collaborative_filtering.dart <UserName>');
    print('Known users: ${ratings.keys.join(', ')}');
    return;
  }
  final String targetUser = args.first;
  if (!ratings.containsKey(targetUser)) {
    print('Unknown user: $targetUser');
    return;
  }



  double cosineSimilarity(
    Map<String, double> u,
    Map<String, double> v,
  ) {
    final commonItems =
        u.keys.where((item) => v.containsKey(item)).toList(growable: false);
    if (commonItems.isEmpty) return 0.0;

    double dot = 0, normU = 0, normV = 0;
    for (final item in commonItems) {
      dot += u[item]! * v[item]!;
    }
    for (final r in u.values) normU += r * r;
    for (final r in v.values) normV += r * r;
    if (normU == 0 || normV == 0) return 0.0;
    return dot / (sqrt(normU) * sqrt(normV));
  }



  final Map<String, double> similarities = {};
  ratings.forEach((otherUser, otherRatings) {
    if (otherUser == targetUser) return;
    similarities[otherUser] =
        cosineSimilarity(ratings[targetUser]!, otherRatings);
  });



  final predicted = <String, double>{};
  final targetItems = ratings[targetUser]!.keys;

  final allItems = <String>{
    for (final m in ratings.values) ...m.keys,
  };

  for (final item in allItems) {
    if (targetItems.contains(item)) continue; 

    double num = 0; 
    double den = 0; 
    ratings.forEach((otherUser, otherRatings) {
      if (!otherRatings.containsKey(item)) return;
      final sim = similarities[otherUser] ?? 0.0;
      if (sim == 0) return;
      num += sim * otherRatings[item]!;
      den += sim.abs();
    });
    if (den != 0) predicted[item] = num / den;
  }



  if (predicted.isEmpty) {
    print('No unseen items to recommend for $targetUser.');
    return;
  }

  final sorted = predicted.entries.toList()
    ..sort((a, b) => b.value.compareTo(a.value));

  print('Recommendations for $targetUser (highest → lowest):');
  for (final e in sorted) {
    print('  ${e.key.padRight(6)}  predicted rating: ${e.value.toStringAsFixed(3)}');
  }
}

import 'dart:math' as math;

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void candidate() {




  final data = <List<double>>[
    [1.0, 2.0],
    [1.2, 2.1],
    [0.8, 1.8],
    [8.0, 8.0],
    [8.2, 8.1],
    [100.0, 100.0], 
  ];

  const double eps = 0.5; 
  const int minPts = 2;   

  final int n = data.length;
  final visited  = List<bool>.filled(n, false);
  final cluster  = List<int>.filled(n, 0); 
  int clusterId  = 0;

  double distance(int i, int j) {
    double sum = 0.0;
    for (var k = 0; k < data[i].length; k++) {
      final diff = data[i][k] - data[j][k];
      sum += diff * diff;
    }
    return math.sqrt(sum);
  }

  List<int> regionQuery(int index) {
    final neighbors = <int>[];
    for (var j = 0; j < n; j++) {
      if (distance(index, j) <= eps) neighbors.add(j);
    }
    return neighbors;
  }

  void expandCluster(int index, List<int> neighbors) {
    cluster[index] = clusterId;
    final seeds = List<int>.from(neighbors);

    while (seeds.isNotEmpty) {
      final current = seeds.removeLast();

      if (!visited[current]) {
        visited[current] = true;
        final currentNeighbors = regionQuery(current);
        if (currentNeighbors.length >= minPts) {
          for (final nb in currentNeighbors) {
            if (!seeds.contains(nb)) seeds.add(nb);
          }
        }
      }

      if (cluster[current] == 0) {
        cluster[current] = clusterId;
      }
    }
  }


  for (var i = 0; i < n; i++) {
    if (visited[i]) continue;

    visited[i] = true;
    final neighbors = regionQuery(i);

    if (neighbors.length < minPts) {
      cluster[i] = -1; 
    } else {
      clusterId++;
      expandCluster(i, neighbors);
    }
  }


  for (var i = 0; i < n; i++) {
    final label = cluster[i] == -1 ? 'Noise' : 'Cluster ${cluster[i]}';
    print('Point ${data[i]} -> $label');
  }
}

extension IntExtensions on int {
  /// Returns true if the integer is even.
  bool get isEven => this % 2 == 0;

  /// Returns true if the integer is odd.
  bool get isOdd => !isEven;

  /// Square of the integer.
  int get squared => this * this;

  /// Runs [action] exactly `this` times, providing the current
  /// 0-based index on each iteration.
  void times(void Function(int index) action) {
    for (var i = 0; i < this; i++) {
      action(i);
    }
  }
}

extension StringExtensions on String {
  /// Capitalizes the first character and returns a new string.
  String capitalize() =>
      isEmpty ? this : '${this[0].toUpperCase()}${substring(1)}';

  /// Returns true if the string reads the same backward as forward.
  bool get isPalindrome => this == split('').reversed.join();
}

extension NumListExtensions on List<num> {
  /// Sum of all numeric elements in the list.
  num get sum => fold<num>(0, (prev, element) => prev + element);

  /// Average value of the elements in the list.
  double get average => isEmpty ? 0 : sum / length;
}

