    final r = rgb[0] / 255.0, g = rgb[1] / 255.0, b = rgb[2] / 255.0;
    final maxC = max(r, max(g, b)), minC = min(r, min(g, b));
    final delta = maxC - minC;
    final l = (maxC + minC) / 2.0;
    double h = 0, s = 0;

    if (delta != 0) {
      s = delta / (1 - (2 * l - 1).abs());
      if (maxC == r) {
        h = 60 * (((g - b) / delta) % 6);
      } else if (maxC == g) {
        h = 60 * (((b - r) / delta) + 2);
      } else {
        h = 60 * (((r - g) / delta) + 4);
      }
    }
    return [h, s, l];
  }

  List<int> hslToRgb(List<double> hsl) {
    double h = hsl[0], s = hsl[1], l = hsl[2];

    final c = (1 - (2 * l - 1).abs()) * s;
    final x = c * (1 - ((h / 60) % 2 - 1).abs());
    final m = l - c / 2;

    double r1 = 0, g1 = 0, b1 = 0;
    if (h < 60) {
      r1 = c; g1 = x; b1 = 0;
    } else if (h < 120) {
      r1 = x; g1 = c; b1 = 0;
    } else if (h < 180) {
      r1 = 0; g1 = c; b1 = x;
    } else if (h < 240) {
      r1 = 0; g1 = x; b1 = c;
    } else if (h < 300) {
      r1 = x; g1 = 0; b1 = c;
    } else {
      r1 = c; g1 = 0; b1 = x;
    }

    return [
      ((r1 + m) * 255).round(),
      ((g1 + m) * 255).round(),
      ((b1 + m) * 255).round()
    ];
  }

