  int minVal = arr.reduce((a, b) => a < b ? a : b);
  int maxVal = arr.reduce((a, b) => a > b ? a : b);
  int range = maxVal - minVal + 1;

  List<int> count = List.filled(range, 0);

  for (int i = 0; i < arr.length; i++) {
