  List<int> output = List.filled(arr.length, 0);


  for (int i = arr.length - 1; i >= 0; i--) {
    int element = arr[i];
    int countIndex = element - minVal;
    output[count[countIndex] - 1] = element;
    count[countIndex]--;
  }

  for (int i = 0; i < arr.length; i++) {
    arr[i] = output[i];
  }

  print('Sorted array: $arr');

  List<int> arr2 = [-3, 5, -1, 0, 2, -3, 4, 1, -2, 3, 0, -1, 2];
  print('\nOriginal array with negatives: $arr2');

