  for (int i = 0; i < arr2.length; i++) {
    count[arr2[i] - minVal]++;
  }

  for (int i = 1; i < count.length; i++) {
    count[i] += count[i - 1];
  }

  output = List.filled(arr2.length, 0);

  for (int i = arr2.length - 1; i >= 0; i--) {
    int element = arr2[i];
    int countIndex = element - minVal;
    output[count[countIndex] - 1] = element;
    count[countIndex]--;
  }

  for (int i = 0; i < arr2.length; i++) {
    arr2[i] = output[i];
  }

  print('Sorted array with negatives: $arr2');

  List<int> digits = [3, 1, 4, 1, 5, 9, 2, 6, 5, 3, 5, 8, 9, 7, 9, 3, 2, 3, 8, 4];
  print('\nOriginal digits array: $digits');

  count = List.filled(10, 0);

  for (int i = 0; i < digits.length; i++) {
    count[digits[i]]++;
  }

  int index = 0;
  for (int i = 0; i < 10; i++) {
