  print('\nAlgorithm verification:');
  int naivePow(int base, int exp) {
    int result = 1;
    for (int i = 0; i < exp; i++) {
      result *= base;
    }
    return result;
  }

  int base = 2;
  int exp = 15;
  int fastResult = fastPow(base, exp);
  int naiveResult = naivePow(base, exp);
  print('Fast: $base^$exp = $fastResult');
  print('Naive: $base^$exp = $naiveResult');
  print('Results match: ${fastResult == naiveResult}');

  print('\nBinary exponentiation process for 2^13:');
  int visualBase = 2;
  int visualExp = 13;
  int visualResult = 1;
  int visualCurrentBase = visualBase;
  int tempExp = visualExp;
  int step = 0;

  print('Computing $visualBase^$visualExp (13 in binary: 1101)');
  while (tempExp > 0) {
    bool bitSet = (tempExp & 1) == 1;
    print('Step ${step++}: bit=${bitSet ? 1 : 0}, ' +
          'currentBase=$visualCurrentBase, ' +
          'result=${bitSet ? visualResult * visualCurrentBase : visualResult}');
    if (bitSet) {
      visualResult *= visualCurrentBase;
    }
    visualCurrentBase *= visualCurrentBase;
    tempExp >>= 1;
  }
  print('Final result: $visualResult');
}

@pragma('vm:never-inline')
