@pragma('vm:never-inline')
@pragma('vm:entry-point')
void candidate() {

  List<List<T>> generateCombinations<T>(List<T> items, int k) {
    List<List<T>> result = [];

    if (k <= 0 || k > items.length) {
      return result;
    }

    if (k == 1) {
      for (var item in items) {
        result.add([item]);
      }
      return result;
    }

    void backtrack(int start, List<T> current) {
      if (current.length == k) {
        result.add(List.from(current));
        return;
      }

      for (int i = start; i < items.length; i++) {
        current.add(items[i]);
        backtrack(i + 1, current);
        current.removeLast();
      }
    }

    backtrack(0, []);
    return result;
  }

  print('Combinations of 3 elements from [1, 2, 3, 4, 5]:');
  List<int> numbers = [1, 2, 3, 4, 5];
  List<List<int>> numCombinations = generateCombinations(numbers, 3);
  for (var combo in numCombinations) {
    print(combo);
  }

  print('\nCombinations of 2 elements from ["A", "B", "C", "D"]:');
  List<String> letters = ['A', 'B', 'C', 'D'];
  List<List<String>> letterCombinations = generateCombinations(letters, 2);
  for (var combo in letterCombinations) {
    print(combo);
  }

  print('\nAll non-empty combinations of [1, 2, 3]:');
  List<int> smallSet = [1, 2, 3];
  for (int k = 1; k <= smallSet.length; k++) {
    print('Size $k combinations:');
    List<List<int>> combos = generateCombinations(smallSet, k);
    for (var combo in combos) {
      print('  $combo');
    }
  }

  print('\nEdge cases:');
  print('Empty list with k=1: ${generateCombinations([], 1)}');
  print('List [1,2] with k=0: ${generateCombinations([1, 2], 0)}');
  print('List [1,2] with k=3: ${generateCombinations([1, 2], 3)}');

  int binomialCoefficient(int n, int k) {
    if (k > n || k < 0) return 0;
    if (k == 0 || k == n) return 1;

    k = k < n - k ? k : n - k;

    int result = 1;
    for (int i = 0; i < k; i++) {
      result = result * (n - i) ~/ (i + 1);
    }
    return result;
  }

  print('\nVerifying combination counts:');
  for (int n = 1; n <= 5; n++) {
    List<int> testList = List.generate(n, (i) => i + 1);
    for (int k = 0; k <= n; k++) {
      int expected = binomialCoefficient(n, k);
      int actual = generateCombinations(testList, k).length;
      print('C($n, $k) = $expected, generated: $actual, match: ${expected == actual}');
    }
  }
}

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void candidate() {

  List<int> set = [1, 2, 3];

  print("Method 1 - Bit Manipulation:");
  List<List<int>> subsets1 = generateSubsetsBitwise(set);
  printSubsets(subsets1);

  print("\nMethod 2 - Recursive approach:");
  List<List<int>> subsets2 = [];
  generateSubsetsRecursive(set, 0, [], subsets2);
  printSubsets(subsets2);

  print("\nMethod 3 - Iterative building:");
  List<List<int>> subsets3 = generateSubsetsIterative(set);
  printSubsets(subsets3);
}

List<List<int>> generateSubsetsBitwise(List<int> set) {
  List<List<int>> allSubsets = [];
  int n = set.length;
  int totalSubsets = 1 << n; 

  for (int i = 0; i < totalSubsets; i++) {
    List<int> subset = [];
    for (int j = 0; j < n; j++) {

      if ((i & (1 << j)) != 0) {
        subset.add(set[j]);
      }
    }
    allSubsets.add(subset);
  }

  return allSubsets;
}

void generateSubsetsRecursive(List<int> set, int index, List<int> current, List<List<int>> result) {
  if (index == set.length) {
    result.add(List.from(current));
    return;
  }

  generateSubsetsRecursive(set, index + 1, current, result);

  current.add(set[index]);
  generateSubsetsRecursive(set, index + 1, current, result);
  current.removeLast(); 
}

List<List<int>> generateSubsetsIterative(List<int> set) {
  List<List<int>> subsets = [[]]; 

  for (int element in set) {
    List<List<int>> newSubsets = [];
    for (List<int> subset in subsets) {
      List<int> newSubset = List.from(subset);
      newSubset.add(element);
      newSubsets.add(newSubset);
    }
    subsets.addAll(newSubsets);
  }

  return subsets;
}

void printSubsets(List<List<int>> subsets) {
  print("Total subsets: ${subsets.length}");
  for (int i = 0; i < subsets.length; i++) {
    if (subsets[i].isEmpty) {
      print("  Subset ${i + 1}: []");
    } else {
      print("  Subset ${i + 1}: {${subsets[i].join(', ')}}");
    }
  }
}

