@pragma('vm:entry-point')
void candidate() {

  List<int> board = List.filled(9, 0);

  void printBoard() {
    for (int i = 0; i < 9; i += 3) {
      String row = '';
      for (int j = 0; j < 3; j++) {
        if (board[i + j] == 0) {
          row += '${i + j} ';
        } else if (board[i + j] == 1) {
          row += 'X ';
        } else {
          row += 'O ';
        }
      }
      print(row);
    }
    print('');
  }

  int checkWinner() {

    for (int i = 0; i < 9; i += 3) {
      if (board[i] != 0 && board[i] == board[i + 1] && board[i] == board[i + 2]) {
        return board[i];
      }
    }

    for (int i = 0; i < 3; i++) {
      if (board[i] != 0 && board[i] == board[i + 3] && board[i] == board[i + 6]) {
        return board[i];
      }
    }

    if (board[0] != 0 && board[0] == board[4] && board[0] == board[8]) {
      return board[0];
    }
    if (board[2] != 0 && board[2] == board[4] && board[2] == board[6]) {
      return board[2];
    }

    return 0; 
  }

  bool isBoardFull() {
    for (int i = 0; i < 9; i++) {
      if (board[i] == 0) return false;
    }
    return true;
  }

  int minimax(bool isMaximizing, int depth) {
    int winner = checkWinner();

    if (winner == 2) return 10 - depth; 
    if (winner == 1) return depth - 10; 
    if (isBoardFull()) return 0; 

    if (isMaximizing) {
      int maxEval = -1000;
      for (int i = 0; i < 9; i++) {
        if (board[i] == 0) {
          board[i] = 2; 
          int eval = minimax(false, depth + 1);
          board[i] = 0;
          if (eval > maxEval) {
            maxEval = eval;
          }
        }
      }
      return maxEval;
    } else {
      int minEval = 1000;
      for (int i = 0; i < 9; i++) {
        if (board[i] == 0) {
          board[i] = 1; 
          int eval = minimax(true, depth + 1);
          board[i] = 0;
          if (eval < minEval) {
            minEval = eval;
          }
        }
      }
      return minEval;
    }
  }

  int findBestMove() {
    int bestMove = -1;
    int bestValue = -1000;

    for (int i = 0; i < 9; i++) {
      if (board[i] == 0) {
        board[i] = 2; 
        int moveValue = minimax(false, 0);
        board[i] = 0;

        if (moveValue > bestValue) {
          bestValue = moveValue;
          bestMove = i;
        }
      }
    }

    return bestMove;
  }

  print('Tic-Tac-Toe with Minimax AI');
  print('You are X, AI is O');
  print('Enter position (0-8) to make your move:\n');

  printBoard();

  List<int> humanMoves = [4, 0, 2]; 
  int moveIndex = 0;

  while (true) {

    if (moveIndex < humanMoves.length) {
      int humanMove = humanMoves[moveIndex];
      if (board[humanMove] == 0) {
        board[humanMove] = 1;
        print('Human plays at position $humanMove');
        printBoard();
        moveIndex++;
      }
    } else {

      for (int i = 0; i < 9; i++) {
        if (board[i] == 0) {
          board[i] = 1;
          print('Human plays at position $i');
          printBoard();
          break;
        }
      }
    }

    int winner = checkWinner();
    if (winner == 1) {
      print('Human wins!');
      break;
    }
    if (isBoardFull()) {
      print('It\'s a draw!');
      break;
    }

    int aiMove = findBestMove();
    if (aiMove != -1) {
      board[aiMove] = 2;
      print('AI plays at position $aiMove');
      printBoard();
    }

    winner = checkWinner();
    if (winner == 2) {
      print('AI wins!');
      break;
    }
    if (isBoardFull()) {
      print('It\'s a draw!');
      break;
    }
  }
}

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void candidate() {

  final List<List<double>> inputs = [
    [0, 0],
    [0, 1],
    [1, 0],
    [1, 1],
  ];

  final List<double> targets = [0, 0, 0, 1]; 

  double weight1 = 0.5;
  double weight2 = 0.5;
  double bias = -0.7;

  final double learningRate = 0.1;

  final int maxEpochs = 100;
  bool trained = false;

  print('Training Perceptron for AND gate...');
  print('Initial weights: w1=$weight1, w2=$weight2, bias=$bias\n');

  for (int epoch = 0; epoch < maxEpochs && !trained; epoch++) {
    int correctPredictions = 0;

    print('Epoch ${epoch + 1}:');

    for (int i = 0; i < inputs.length; i++) {

      double x1 = inputs[i][0];
      double x2 = inputs[i][1];
      double target = targets[i];

      double weightedSum = x1 * weight1 + x2 * weight2 + bias;

      double output = weightedSum > 0 ? 1.0 : 0.0;

      double error = target - output;

      if (error != 0) {
        weight1 += learningRate * error * x1;
        weight2 += learningRate * error * x2;
        bias += learningRate * error;

        print('  Input: [${x1.toInt()}, ${x2.toInt()}], Target: ${target.toInt()}, Output: ${output.toInt()}, Error: $error');
        print('  Updated weights: w1=$weight1, w2=$weight2, bias=$bias');
      } else {
        correctPredictions++;
      }
    }

    if (correctPredictions == inputs.length) {
      trained = true;
      print('\nTraining completed at epoch ${epoch + 1}!');
    }
  }

  if (!trained) {
    print('\nMax epochs reached. Training may not be complete.');
  }

  print('\nFinal weights:');
  print('  w1 = $weight1');
  print('  w2 = $weight2');
  print('  bias = $bias');

  print('\nTesting the trained perceptron:');
  print('Input | Target | Prediction');
  print('------|--------|------------');

  for (int i = 0; i < inputs.length; i++) {
    double x1 = inputs[i][0];
    double x2 = inputs[i][1];
    double target = targets[i];

    double weightedSum = x1 * weight1 + x2 * weight2 + bias;
    double prediction = weightedSum > 0 ? 1.0 : 0.0;

    print('[${x1.toInt()}, ${x2.toInt()}] |   ${target.toInt()}    |     ${prediction.toInt()}');
  }

  print('\n--- Testing with OR gate (without retraining) ---');
  final List<List<double>> orInputs = [
    [0, 0],
    [0, 1],
    [1, 0],
    [1, 1],
  ];
  final List<double> orTargets = [0, 1, 1, 1]; 

  print('Input | OR Target | Prediction');
  print('------|-----------|------------');

  int orCorrect = 0;
  for (int i = 0; i < orInputs.length; i++) {
    double x1 = orInputs[i][0];
    double x2 = orInputs[i][1];
    double target = orTargets[i];

    double weightedSum = x1 * weight1 + x2 * weight2 + bias;
    double prediction = weightedSum > 0 ? 1.0 : 0.0;

    if (prediction == target) orCorrect++;

    print('[${x1.toInt()}, ${x2.toInt()}] |     ${target.toInt()}     |     ${prediction.toInt()}');
  }

  print('\nAccuracy on OR gate: ${orCorrect}/${orInputs.length} = ${(orCorrect / orInputs.length * 100).toStringAsFixed(1)}%');
  print('\nNote: The perceptron was trained for AND gate, not OR gate.');
  print('Different logic gates require different weight configurations.');
}

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void candidate() {

  final Map<int, List<int>> graph = {
    0: [1, 2],    
    1: [2],       
    2: [0],       
    3: [2],       
    4: [1, 3],    
  };

  final double dampingFactor = 0.85;
  final int maxIterations = 100;
  final double convergenceThreshold = 0.0001;

  final Set<int> allPages = {};
  graph.forEach((key, value) {
    allPages.add(key);
    allPages.addAll(value);
  });
  final int numPages = allPages.length;

  final Map<int, double> pageRank = {};
  final Map<int, double> newPageRank = {};
  for (int page in allPages) {
    pageRank[page] = 1.0 / numPages;
    newPageRank[page] = 0.0;
  }

  final Map<int, int> outgoingLinks = {};
  for (int page in allPages) {
    outgoingLinks[page] = graph[page]?.length ?? 0;
  }

  final Map<int, List<int>> incomingLinks = {};
  for (int page in allPages) {
    incomingLinks[page] = [];
  }
  graph.forEach((fromPage, toPages) {
    for (int toPage in toPages) {
      incomingLinks[toPage]?.add(fromPage);
    }
  });

  print('Starting PageRank calculation...');
  print('Number of pages: $numPages');
  print('Damping factor: $dampingFactor');
  print('Max iterations: $maxIterations');
  print('Convergence threshold: $convergenceThreshold\n');

  bool converged = false;
  int iteration = 0;

  while (iteration < maxIterations && !converged) {

    for (int page in allPages) {
      double rank = (1.0 - dampingFactor) / numPages;

      for (int incomingPage in incomingLinks[page]!) {
        if (outgoingLinks[incomingPage]! > 0) {
          rank += dampingFactor * (pageRank[incomingPage]! / outgoingLinks[incomingPage]!);
        }
      }

      double danglingContribution = 0.0;
      for (int p in allPages) {
        if (outgoingLinks[p] == 0) {
          danglingContribution += pageRank[p]!;
        }
      }
      rank += dampingFactor * (danglingContribution / numPages);

      newPageRank[page] = rank;
    }

    double maxDiff = 0.0;
    for (int page in allPages) {
      double diff = (newPageRank[page]! - pageRank[page]!).abs();
      if (diff > maxDiff) {
        maxDiff = diff;
      }
    }

    if (maxDiff < convergenceThreshold) {
      converged = true;
    }

    for (int page in allPages) {
      pageRank[page] = newPageRank[page]!;
    }

    iteration++;

    if (iteration % 10 == 0 || converged) {
      print('Iteration $iteration: Max difference = ${maxDiff.toStringAsFixed(6)}');
    }
  }

  double sum = 0.0;
  for (int page in allPages) {
    sum += pageRank[page]!;
  }
  for (int page in allPages) {
    pageRank[page] = pageRank[page]! / sum;
  }

  final List<MapEntry<int, double>> sortedPageRank = pageRank.entries.toList()
    ..sort((a, b) => b.value.compareTo(a.value));

  print('\n' + '=' * 50);
  print('PageRank Results (after $iteration iterations):');
  print('=' * 50);

  for (var entry in sortedPageRank) {
    print('Page ${entry.key}: ${entry.value.toStringAsFixed(6)} (${(entry.value * 100).toStringAsFixed(2)}%)');
  }

  double totalPageRank = 0.0;
  for (int page in allPages) {
    totalPageRank += pageRank[page]!;
  }
  print('\nTotal PageRank sum: ${totalPageRank.toStringAsFixed(6)}');

  print('\n' + '=' * 50);
  print('Graph Structure:');
  print('=' * 50);
  for (int page in allPages) {
    if (graph[page] != null && graph[page]!.isNotEmpty) {
      print('Page $page -> ${graph[page]}');
    } else {
      print('Page $page -> [] (dangling node)');
    }
  }
}

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void candidate() {

  List<List<String>> transactions = [
    ['milk', 'bread', 'butter'],
    ['milk', 'bread'],
    ['beer', 'chips', 'salsa'],
    ['milk', 'bread', 'butter', 'cheese'],
    ['beer', 'chips'],
    ['milk', 'butter'],
    ['bread', 'butter'],
    ['beer', 'salsa'],
    ['milk', 'bread', 'cheese'],
    ['beer', 'chips', 'salsa'],
  ];

  double minSupport = 0.3; 
  double minConfidence = 0.6; 

  print('Transactions:');
  for (int i = 0; i < transactions.length; i++) {
    print('T${i + 1}: ${transactions[i]}');
  }
  print('\nMinimum Support: ${(minSupport * 100).toStringAsFixed(0)}%');
  print('Minimum Confidence: ${(minConfidence * 100).toStringAsFixed(0)}%\n');

  Map<Set<String>, int> itemCounts = {};
  for (var transaction in transactions) {
    for (var item in transaction) {
      Set<String> itemSet = {item};
      itemCounts[itemSet] = (itemCounts[itemSet] ?? 0) + 1;
    }
  }

  Map<Set<String>, double> frequentItemsets = {};
  Map<Set<String>, double> currentFrequent = {};

  for (var entry in itemCounts.entries) {
    double support = entry.value / transactions.length;
    if (support >= minSupport) {
      currentFrequent[entry.key] = support;
      frequentItemsets[entry.key] = support;
    }
  }

  print('Frequent 1-itemsets:');
  for (var entry in currentFrequent.entries) {
    print('  ${entry.key.toList()}: Support = ${(entry.value * 100).toStringAsFixed(1)}%');
  }

  int k = 2;
  while (currentFrequent.isNotEmpty) {
    print('\nGenerating ${k}-itemsets...');

    Map<Set<String>, int> candidateCounts = {};
    List<Set<String>> frequentList = currentFrequent.keys.toList();

    for (int i = 0; i < frequentList.length; i++) {
      for (int j = i + 1; j < frequentList.length; j++) {
        Set<String> union = {...frequentList[i], ...frequentList[j]};
        if (union.length == k) {

          bool allSubsetsFrequent = true;
          List<String> unionList = union.toList();

          for (int idx = 0; idx < unionList.length; idx++) {
            Set<String> subset = {...unionList};
            subset.remove(unionList[idx]);
            if (!currentFrequent.containsKey(subset) && k > 2) {
              bool found = false;
              for (var freq in frequentItemsets.keys) {
                if (freq.length == subset.length && 
                    freq.containsAll(subset) && 
                    subset.containsAll(freq)) {
                  found = true;
                  break;
                }
              }
              if (!found) {
                allSubsetsFrequent = false;
                break;
              }
            }
          }

          if (allSubsetsFrequent) {
            candidateCounts[union] = 0;
          }
        }
      }
    }

    for (var transaction in transactions) {
      Set<String> transactionSet = transaction.toSet();
      for (var candidate in candidateCounts.keys) {
        if (candidate.every((item) => transactionSet.contains(item))) {
          candidateCounts[candidate] = candidateCounts[candidate]! + 1;
        }
      }
    }

    currentFrequent.clear();
    for (var entry in candidateCounts.entries) {
      double support = entry.value / transactions.length;
      if (support >= minSupport) {
        currentFrequent[entry.key] = support;
        frequentItemsets[entry.key] = support;
      }
    }

    if (currentFrequent.isNotEmpty) {
      print('Frequent ${k}-itemsets:');
      for (var entry in currentFrequent.entries) {
        List<String> items = entry.key.toList()..sort();
        print('  ${items}: Support = ${(entry.value * 100).toStringAsFixed(1)}%');
      }
    } else {
      print('No frequent ${k}-itemsets found.');
    }

    k++;
  }

  print('\n' + '=' * 50);
  print('ASSOCIATION RULES:');
  print('=' * 50);

  List<Map<String, dynamic>> rules = [];

  for (var itemset in frequentItemsets.keys) {
    if (itemset.length >= 2) {
      List<String> items = itemset.toList();

      for (int i = 1; i < (1 << items.length) - 1; i++) {
        Set<String> antecedent = {};
        Set<String> consequent = {};

        for (int j = 0; j < items.length; j++) {
          if ((i & (1 << j)) != 0) {
            antecedent.add(items[j]);
          } else {
            consequent.add(items[j]);
          }
        }

        if (antecedent.isNotEmpty && consequent.isNotEmpty) {

          double itemsetSupport = frequentItemsets[itemset]!;
          double antecedentSupport = 0;

          for (var freq in frequentItemsets.entries) {
            if (freq.key.length == antecedent.length &&
                freq.key.containsAll(antecedent) &&
                antecedent.containsAll(freq.key)) {
              antecedentSupport = freq.value;
              break;
            }
          }

          if (antecedentSupport > 0) {
            double confidence = itemsetSupport / antecedentSupport;

            if (confidence >= minConfidence) {
              double lift = confidence / (frequentItemsets[consequent] ?? 1.0);

              rules.add({
                'antecedent': antecedent.toList()..sort(),
                'consequent': consequent.toList()..sort(),
                'support': itemsetSupport,
                'confidence': confidence,
                'lift': lift,
              });
            }
          }
        }
      }
    }
  }

  rules.sort((a, b) => b['confidence'].compareTo(a['confidence']));

  if (rules.isEmpty) {
    print('No association rules found with the given thresholds.');
  } else {
    print('\nFound ${rules.length} association rules:\n');
    for (var rule in rules) {
      print('${rule['antecedent']} => ${rule['consequent']}');
      print('  Support: ${(rule['support'] * 100).toStringAsFixed(1)}%');
      print('  Confidence: ${(rule['confidence'] * 100).toStringAsFixed(1)}%');
      print('  Lift: ${rule['lift'].toStringAsFixed(2)}');
      print('');
    }
  }

  print('=' * 50);
  print('SUMMARY:');
  print('=' * 50);
  print('Total transactions: ${transactions.length}');
  print('Total frequent itemsets: ${frequentItemsets.length}');
  print('Total association rules: ${rules.length}');

  if (rules.isNotEmpty) {
    var strongestRule = rules.first;
    print('\nStrongest rule (by confidence):');
    print('${strongestRule['antecedent']} => ${strongestRule['consequent']}');
    print('Confidence: ${(strongestRule['confidence'] * 100).toStringAsFixed(1)}%');
  }
}

