void candidate() {


  bool matchWildcard(String pattern, String text) {
    int m = pattern.length;
    int n = text.length;

    List<List<bool>> dp = List.generate(
      m + 1,
      (_) => List.filled(n + 1, false),
    );

    dp[0][0] = true;

    for (int i = 1; i <= m; i++) {
      if (pattern[i - 1] == '*') {
        dp[i][0] = dp[i - 1][0];
      }
    }

    for (int i = 1; i <= m; i++) {
      for (int j = 1; j <= n; j++) {
        if (pattern[i - 1] == '*') {

          dp[i][j] = dp[i - 1][j] || dp[i][j - 1];
        } else if (pattern[i - 1] == '?' || pattern[i - 1] == text[j - 1]) {

          dp[i][j] = dp[i - 1][j - 1];
        }
      }
    }

    return dp[m][n];
  }

  List<Map<String, dynamic>> testCases = [
    {'pattern': 'a*b', 'text': 'axxxb', 'expected': true},
    {'pattern': 'a*b', 'text': 'ab', 'expected': true},
    {'pattern': 'a?b', 'text': 'axb', 'expected': true},
    {'pattern': 'a?b', 'text': 'ab', 'expected': false},
    {'pattern': '*', 'text': 'anything', 'expected': true},
    {'pattern': 'a*', 'text': 'abc', 'expected': true},
    {'pattern': '*b', 'text': 'xyzb', 'expected': true},
    {'pattern': 'a?c', 'text': 'abc', 'expected': true},
