    {'pattern': '?*', 'text': '', 'expected': false},
    {'pattern': 'h*llo', 'text': 'hello', 'expected': true},
    {'pattern': 'h*llo', 'text': 'heeeello', 'expected': true},
    {'pattern': 'h?llo', 'text': 'hello', 'expected': true},
    {'pattern': 'h?llo', 'text': 'hallo', 'expected': true},
    {'pattern': 'h?llo', 'text': 'hllo', 'expected': false},
    {'pattern': '*world*', 'text': 'hello world!', 'expected': true},
    {'pattern': '*.txt', 'text': 'file.txt', 'expected': true},
    {'pattern': '*.txt', 'text': 'file.doc', 'expected': false},
