abstract class Shape {
  double calculateArea();
  double calculatePerimeter();
  String describe();
}

final class Circle extends Shape {
  final double radius;

  Circle(this.radius);

  @override
  double calculateArea() {
    return 3.14159 * radius * radius;
  }

  @override
  double calculatePerimeter() {
    return 2 * 3.14159 * radius;
  }

  @override
  String describe() {
    return 'Circle(radius: $radius)';
  }
}

final class Rectangle extends Shape {
  final double width;
  final double height;

  Rectangle(this.width, this.height);

  @override
  double calculateArea() {
    return width * height;
  }

  @override
  double calculatePerimeter() {
    return 2 * (width + height);
  }

  @override
  String describe() {
    return 'Rectangle(width: $width, height: $height)';
  }
}

final class Square extends Shape {
  final double side;

  Square(this.side);

  @override
  double calculateArea() {
    return side * side;
  }

  @override
  double calculatePerimeter() {
    return 4 * side;
  }

  @override
  String describe() {
    return 'Square(side: $side)';
  }
}

final class Color {
  final int red;
  final int green;
  final int blue;

  Color(this.red, this.green, this.blue) {
    if (red < 0 || red > 255 || 
        green < 0 || green > 255 || 
        blue < 0 || blue > 255) {
      throw ArgumentError('Color values must be between 0 and 255');
    }
  }

  String toHex() {
    return '#${red.toRadixString(16).padLeft(2, '0')}'
           '${green.toRadixString(16).padLeft(2, '0')}'
           '${blue.toRadixString(16).padLeft(2, '0')}';
  }

  @override
  String toString() {
    return 'Color(r: $red, g: $green, b: $blue)';
  }
}

final class User {
  final String name;
  final int age;
  final bool isAdmin;

  User._(this.name, this.age, this.isAdmin);

  factory User.create(String name, int age) {
    return User._(name, age, false);
  }

  factory User.createAdmin(String name, int age) {
    return User._(name, age, true);
  }

  @override
  String toString() {
    return 'User(name: $name, age: $age, isAdmin: $isAdmin)';
  }
}

