  final gesturePatterns = {
    'swipe_left': 'left',
    'swipe_right': 'right',
    'swipe_up': 'up',
    'swipe_down': 'down',
    'double_tap': 'back',
    'long_press': 'home',
    'pinch': 'menu',
    'rotate': 'refresh'
  };

  void processGesture(String gesture) {
    print('\n🎯 Gesture detected: $gesture');
    gestureHistory.add(gesture);

    if (gesture == 'double_tap') {

      if (navigationStack.length > 1) {
        navigationStack.removeLast();
        currentScreen = navigationStack.last;
        print('↩️  Navigating back to: $currentScreen');
      } else {
        print('⚠️  Already at root screen');
      }
    } else if (gesture == 'long_press') {

      currentScreen = 'Home';
      navigationStack = ['Home'];
      print('🏠 Returning to Home');
    } else if (gesture == 'pinch') {

      print('📱 Opening menu...');
      print('   Available screens: ${screens.keys.join(', ')}');
    } else if (gesture == 'rotate') {

      print('🔄 Refreshing $currentScreen...');
    } else if (gesturePatterns.containsKey(gesture)) {

      var direction = gesturePatterns[gesture]!;
      if (screens[currentScreen]?.containsKey(direction) ?? false) {
        var nextScreen = screens[currentScreen]![direction]!;
        currentScreen = nextScreen;
        navigationStack.add(nextScreen);
        print('➡️  Navigating to: $nextScreen');
      } else {
        print('⚠️  No navigation available for $gesture from $currentScreen');
      }
    }

    print('📍 Current location: $currentScreen');
    print('📚 Navigation stack: ${navigationStack.join(' > ')}');
  }

  void performGestureCombination(List<String> gestures) {
    print('\n🎮 Performing gesture combination: ${gestures.join(' + ')}');

    if (gestures.length == 2) {
      if (gestures.contains('swipe_up') && gestures.contains('swipe_down')) {
        print('🔍 Zoom gesture detected - Adjusting view');
      } else if (gestures.contains('swipe_left') && gestures.contains('swipe_right')) {
        print('🔄 Cancel gesture detected - Action cancelled');
      } else {
        print('⚡ Quick action triggered');
      }
    } else if (gestures.length == 3) {
      print('🎯 Advanced gesture pattern recognized');
      print('🚀 Launching special feature...');
    }
  }

  void analyzeGestureVelocity(String gesture, double velocity) {
    print('\n📊 Analyzing gesture velocity...');
    print('   Gesture: $gesture');
    print('   Velocity: ${velocity.toStringAsFixed(2)} px/ms');

    if (velocity > 2.0) {
      print('   ⚡ Fast gesture - Quick navigation');
    } else if (velocity > 1.0) {
      print('   🚶 Normal gesture - Standard navigation');
    } else {
      print('   🐌 Slow gesture - Precise control mode');
    }
  }

  void detectPattern() {
    if (gestureHistory.length >= 3) {
      var recentGestures = gestureHistory.sublist(gestureHistory.length - 3);
      print('\n🔍 Pattern detection...');
      print('   Recent gestures: ${recentGestures.join(' → ')}');

      if (recentGestures.join(',') == 'swipe_up,swipe_up,swipe_down') {
        print('   ✨ Secret pattern detected! Unlocking hidden feature...');
      } else if (recentGestures.every((g) => g == recentGestures[0])) {
        print('   🔁 Repetitive pattern detected - Activating quick mode');
      }
    }
  }

  print('🚀 Gesture-Based Navigation System');
  print('=' * 50);

  var simulatedGestures = [
    'swipe_right',
    'swipe_up',
    'swipe_left',
    'double_tap',
    'swipe_down',
    'long_press',
    'swipe_up',
    'swipe_right',
    'pinch',
    'rotate',
    'swipe_left',
    'swipe_up',
    'swipe_up',
    'swipe_down'
  ];

  for (var gesture in simulatedGestures) {
    processGesture(gesture);

    if (gesture.startsWith('swipe')) {
      var velocity = 0.5 + (gesture.hashCode % 20) / 10.0;
      analyzeGestureVelocity(gesture, velocity);
    }

    if (gestureHistory.length % 3 == 0) {
      detectPattern();
    }
  }

  print('\n' + '=' * 50);
  print('🎯 Testing Gesture Combinations');
  print('=' * 50);

  performGestureCombination(['swipe_up', 'swipe_down']);
  performGestureCombination(['swipe_left', 'swipe_right']);
  performGestureCombination(['swipe_up', 'swipe_right', 'double_tap']);

  print('\n' + '=' * 50);
  print('📈 Navigation Statistics');
  print('=' * 50);

  var gestureCount = <String, int>{};
  for (var gesture in gestureHistory) {
    gestureCount[gesture] = (gestureCount[gesture] ?? 0) + 1;
  }

  print('Total gestures performed: ${gestureHistory.length}');
  print('Unique screens visited: ${navigationStack.toSet().length}');
  print('\nGesture frequency:');
  gestureCount.forEach((gesture, count) {
    var percentage = (count / gestureHistory.length * 100).toStringAsFixed(1);
    var bar = '█' * (count * 3);
    print('  $gesture: $bar $count ($percentage%)');
  });

  var backNavigations = gestureHistory.where((g) => g == 'double_tap').length;
  var homeNavigations = gestureHistory.where((g) => g == 'long_press').length;
  var efficiency = ((gestureHistory.length - backNavigations - homeNavigations) / 
                    gestureHistory.length * 100).toStringAsFixed(1);

  print('\nNavigation efficiency: $efficiency%');
  print('Back navigations: $backNavigations');
  print('Home navigations: $homeNavigations');

  print('\n' + '=' * 50);
  print('💡 Gesture Recommendations');
  print('=' * 50);

  var mostUsedGesture = gestureCount.entries
      .reduce((a, b) => a.value > b.value ? a : b)
      .key;

  print('Your most used gesture: $mostUsedGesture');
  print('Tip: Try using gesture combinations for faster navigation');
  print('Hint: Double-tap to go back, long-press to go home');

  print('\n' + '=' * 50);
  print('🗺️ Gesture Heatmap');
  print('=' * 50);

  var directions = ['up', 'right', 'down', 'left'];
  var heatmap = List.generate(3, (_) => List.filled(3, 0));

  for (var gesture in gestureHistory) {
    if (gesture == 'swipe_up') heatmap[0][1]++;
    if (gesture == 'swipe_right') heatmap[1][2]++;
    if (gesture == 'swipe_down') heatmap[2][1]++;
    if (gesture == 'swipe_left') heatmap[1][0]++;
  }

  print('   ↑');
  for (var row in heatmap) {
    var rowStr = row.map((val) {
      if (val == 0) return '⬜';
      if (val <= 2) return '🟦';
      if (val <= 4) return '🟨';
      return '🟥';
    }).join(' ');
    print('← $rowStr →');
  }
  print('   ↓');

  print('\n🎉 Navigation session complete!');
}

@pragma('vm:never-inline')
@pragma('vm:entry-point')
void candidate() {

  const permissions = {
    'read': 1,
    'write': 2,
    'delete': 4,
    'admin': 8,
  };

  final roles = {
    'viewer': ['read'],
    'editor': ['read', 'write'],
    'moderator': ['read', 'write', 'delete'],
    'admin': ['read', 'write', 'delete', 'admin'],
  };

  final users = {
    'alice': 'admin',
    'bob': 'editor',
    'charlie': 'viewer',
    'diana': 'moderator',
  };

  final resources = {
    'document1': ['read'],
    'document2': ['read', 'write'],
    'sensitive_data': ['read', 'admin'],
    'user_management': ['admin'],
    'content_moderation': ['delete'],
  };

  int getRolePermissions(String role) {
    if (!roles.containsKey(role)) return 0;

    int permissionMask = 0;
    for (String perm in roles[role]!) {
      permissionMask |= permissions[perm] ?? 0;
    }
    return permissionMask;
  }

  int getResourceRequirements(String resource) {
    if (!resources.containsKey(resource)) return 0;

    int requiredMask = 0;
    for (String perm in resources[resource]!) {
      requiredMask |= permissions[perm] ?? 0;
    }
    return requiredMask;
  }

  bool hasAccess(String username, String resource) {
    if (!users.containsKey(username)) {
      print('  ❌ User "$username" not found');
      return false;
    }

    String userRole = users[username]!;
    int userPermissions = getRolePermissions(userRole);
    int requiredPermissions = getResourceRequirements(resource);

    return (userPermissions & requiredPermissions) == requiredPermissions;
  }

  void displayUserPermissions(String username) {
    if (!users.containsKey(username)) {
      print('User "$username" not found\n');
      return;
    }

    String userRole = users[username]!;
    int userPermissions = getRolePermissions(userRole);

    print('User: $username');
    print('Role: $userRole');
    print('Permissions:');

    permissions.forEach((permName, permValue) {
      if ((userPermissions & permValue) != 0) {
        print('  ✓ $permName');
      } else {
        print('  ✗ $permName');
      }
    });
    print('');
  }

  void attemptAction(String username, String action, String resource) {
    print('$username attempts to $action "$resource"...');

    final actionPermissions = {
      'view': ['read'],
      'edit': ['write'],
      'remove': ['delete'],
      'manage': ['admin'],
    };

    if (!actionPermissions.containsKey(action)) {
      print('  ❌ Unknown action: $action\n');
      return;
    }

    if (!users.containsKey(username)) {
      print('  ❌ User not found\n');
      return;
    }

    if (!resources.containsKey(resource)) {
      print('  ❌ Resource not found\n');
      return;
    }

    String userRole = users[username]!;
    int userPermissions = getRolePermissions(userRole);

    bool canPerformAction = true;
    for (String requiredPerm in actionPermissions[action]!) {
      int permValue = permissions[requiredPerm] ?? 0;
      if ((userPermissions & permValue) == 0) {
        canPerformAction = false;
        break;
      }
    }

    if (canPerformAction && hasAccess(username, resource)) {
      print('  ✅ Access GRANTED (Role: $userRole)\n');
    } else {
      print('  ❌ Access DENIED (Insufficient permissions)\n');
    }
  }

  print('=== Role-Based Access Control System ===\n');

  print('--- User Permissions Overview ---\n');
  for (String user in users.keys) {
    displayUserPermissions(user);
  }

  print('--- Access Control Tests ---\n');

  attemptAction('alice', 'view', 'document1');
  attemptAction('alice', 'manage', 'user_management');
  attemptAction('bob', 'edit', 'document2');
  attemptAction('bob', 'manage', 'user_management');
  attemptAction('charlie', 'view', 'document1');
  attemptAction('charlie', 'edit', 'document2');
  attemptAction('diana', 'remove', 'content_moderation');
  attemptAction('diana', 'manage', 'user_management');

  print('--- Resource Access Matrix ---\n');

  print('User/Resource Access Matrix:');
  print('-' * 70);

  String header = 'User'.padRight(12);
  for (String resource in resources.keys) {
    header += resource.padRight(20);
  }
  print(header);
  print('-' * 70);

  for (String user in users.keys) {
    String row = user.padRight(12);
    for (String resource in resources.keys) {
      if (hasAccess(user, resource)) {
        row += '✅'.padRight(20);
      } else {
        row += '❌'.padRight(20);
      }
    }
    print(row);
  }

  print('\n--- Permission Inheritance Demo ---\n');

  print('Role Hierarchy:');
  print('  Admin    -> [read, write, delete, admin]');
  print('  Moderator -> [read, write, delete]');
  print('  Editor   -> [read, write]');
  print('  Viewer   -> [read]\n');

  print('--- Permission Elevation Scenario ---\n');

  String testUser = 'bob';
  print('Current role for $testUser: ${users[testUser]}');
  print('Attempting to access admin resource...');
  if (hasAccess(testUser, 'user_management')) {
    print('  ✅ Access granted\n');
  } else {
    print('  ❌ Access denied\n');
  }

  print('Elevating $testUser to admin role...');
  users[testUser] = 'admin';
  print('New role for $testUser: ${users[testUser]}');
  print('Attempting to access admin resource again...');
  if (hasAccess(testUser, 'user_management')) {
    print('  ✅ Access granted\n');
  } else {
    print('  ❌ Access denied\n');
  }

  users[testUser] = 'editor';

  print('--- Audit Log ---\n');

  final auditLog = [
    {'timestamp': '2024-01-01 10:00:00', 'user': 'alice', 'action': 'CREATE', 'resource': 'document1', 'status': 'SUCCESS'},
    {'timestamp': '2024-01-01 10:05:00', 'user': 'bob', 'action': 'EDIT', 'resource': 'document2', 'status': 'SUCCESS'},
    {'timestamp': '2024-01-01 10:10:00', 'user': 'charlie', 'action': 'DELETE', 'resource': 'document1', 'status': 'DENIED'},
    {'timestamp': '2024-01-01 10:15:00', 'user': 'diana', 'action': 'DELETE', 'resource': 'content_moderation', 'status': 'SUCCESS'},
  ];

  print('Recent Access Attempts:');
  for (var entry in auditLog) {
    String status = entry['status'] == 'SUCCESS' ? '✅' : '❌';
    print('  $status [${entry['timestamp']}] ${entry['user']} -> ${entry['action']} ${entry['resource']}');
  }

  print('\n=== System Summary ===');
  print('Total Users: ${users.length}');
  print('Total Roles: ${roles.length}');
  print('Total Resources: ${resources.length}');
  print('Total Permissions: ${permissions.length}');
}

