int _calculateCompletionPercentage(Map<String, dynamic> profile) {
  var fields = ['name', 'email', 'age', 'preferences', 'profilePicture', 'bio', 'notificationsEnabled', 'locationEnabled'];
  var completed = 0;

  for (var field in fields) {
    if (profile[field] != null) {
      if (field == 'preferences' && (profile[field] as List).isNotEmpty) {
        completed++;
      } else if (field != 'preferences') {
        completed++;
      }
    }
  }

  return (completed / fields.length * 100).round();
}

