void candidate() {

  List<int> remainders = [2, 3, 2];
  List<int> moduli = [3, 5, 7];

  List<int> extGcd(int a, int b) {
    int oldR = a, r = b;
    int oldS = 1, s = 0;
    int oldT = 0, t = 1;
    while (r != 0) {
      int q = oldR ~/ r;
      int tmp = r;
      r = oldR - q * r;
      oldR = tmp;
      tmp = s;
      s = oldS - q * s;
      oldS = tmp;
      tmp = t;
      t = oldT - q * t;
      oldT = tmp;
    }
    return [oldR, oldS, oldT];
  }

  int modInverse(int a, int m) {
    var eg = extGcd(a, m);
    int gcd = eg[0], x = eg[1];
    if (gcd != 1) {
      throw ArgumentError('Modular inverse does not exist for $a mod $m');
    }
    return (x % m + m) % m;
  }

  int N = 1;
  for (var ni in moduli) {
    N *= ni;
  }

  int result = 0;
  for (int i = 0; i < moduli.length; i++) {
    int ni = moduli[i];
    int ai = remainders[i];
    int Ni = N ~/ ni;
    int inv = modInverse(Ni, ni);
    result += ai * Ni * inv;
  }
  result %= N;

  print('Solution: x ≡ $result (mod $N)');
}

