      do {
        w = stack.removeLast();
        onStack[w] = false;
        scc.add(w);
      } while (w != v);
      sccs.add(scc);
    }
  }

  for (var v = 0; v < n; v++) {
    if (indices[v] == -1) {
      strongConnect(v);
    }
