  visited[0][0] = true;
  stack.add(Point(0, 0));

  while (stack.isNotEmpty) {
    final current = stack.last;
    final x = current.x;
    final y = current.y;

    final neighbors = <int>[];
    for (final dir in [N, S, E, W]) {
      final nx = x + dx[dir]!;
      final ny = y + dy[dir]!;
      if (nx >= 0 &&
          nx < width &&
          ny >= 0 &&
          ny < height &&
          !visited[ny][nx]) {
        neighbors.add(dir);
      }
    }

    if (neighbors.isNotEmpty) {

      final dir = neighbors[rand.nextInt(neighbors.length)];
      final nx = x + dx[dir]!;
      final ny = y + dy[dir]!;

      grid[y][x] &= ~dir;
      grid[ny][nx] &= ~opposite[dir]!;

      visited[ny][nx] = true;
      stack.add(Point(nx, ny));
    } else {

      stack.removeLast();
    }
