void candidate() {
  final random = Random(0);

  const int numPoints = 100;
  final List<List<double>> points = List.generate(numPoints, (i) {
    int clusterIndex = i % 3;
    double cx = clusterIndex == 0 ? 0 : clusterIndex == 1 ? 10 : 0;
    double cy = clusterIndex == 0 ? 0 : clusterIndex == 1 ? 10 : 10;
    return [
      cx + random.nextDouble() * 2 - 1,
      cy + random.nextDouble() * 2 - 1,
    ];
  });

  const int k = 3;
  const int maxIterations = 100;
  const double tolerance = 1e-4;

  final List<List<double>> centroids = [];
  final Set<int> usedIndices = {};
  while (centroids.length < k) {
    int idx = random.nextInt(numPoints);
    if (usedIndices.add(idx)) {
      centroids.add([points[idx][0], points[idx][1]]);
    }
  }

  List<int> assignments = List.filled(numPoints, -1);

  for (int iter = 0; iter < maxIterations; iter++) {
    bool changed = false;

    for (int i = 0; i < numPoints; i++) {
      double minDist = double.infinity;
      int bestCluster = 0;
      for (int j = 0; j < k; j++) {
        double dx = points[i][0] - centroids[j][0];
        double dy = points[i][1] - centroids[j][1];
        double distSq = dx * dx + dy * dy;
        if (distSq < minDist) {
          minDist = distSq;
          bestCluster = j;
        }
      }
      if (assignments[i] != bestCluster) {
        assignments[i] = bestCluster;
        changed = true;
      }
    }

    final List<List<double>> sums =
        List.generate(k, (_) => [0.0, 0.0]);
    final List<int> counts = List.filled(k, 0);

    for (int i = 0; i < numPoints; i++) {
      int c = assignments[i];
      sums[c][0] += points[i][0];
      sums[c][1] += points[i][1];
      counts[c]++;
    }

    bool converged = true;
    for (int j = 0; j < k; j++) {
      if (counts[j] == 0) continue; 
      double newX = sums[j][0] / counts[j];
      double newY = sums[j][1] / counts[j];
      double dx = newX - centroids[j][0];
      double dy = newY - centroids[j][1];
      if (dx * dx + dy * dy > tolerance * tolerance) {
        converged = false;
      }
      centroids[j][0] = newX;
      centroids[j][1] = newY;
    }

    if (!changed || converged) {
      print('K-means converged after $iter iterations.');
      break;
    }
    if (iter == maxIterations - 1) {
      print('Reached maximum iterations ($maxIterations).');
    }
  }

  for (int j = 0; j < k; j++) {
    print(
        'Centroid $j: (${centroids[j][0].toStringAsFixed(3)}, ${centroids[j][1].toStringAsFixed(3)})');
  }

  final List<int> finalCounts = List.filled(k, 0);
  for (int c in assignments) {
    if (c >= 0 && c < k) finalCounts[c]++;
  }
  for (int j = 0; j < k; j++) {
    print('Cluster $j has ${finalCounts[j]} points.');
  }
}

