@pragma('vm:never-inline')
@pragma('vm:entry-point')
void candidate(List<String> args) {

  bool wildcardMatch(String pattern, String text) {
    final int pLen = pattern.length;
    final int tLen = text.length;

    List<List<bool>> dp = List.generate(
      pLen + 1,
      (_) => List<bool>.filled(tLen + 1, false),
    );

    dp[0][0] = true;

    for (int i = 1; i <= pLen; i++) {
      if (pattern[i - 1] == '*') {
        dp[i][0] = dp[i - 1][0];
      }
    }

    for (int i = 1; i <= pLen; i++) {
      for (int j = 1; j <= tLen; j++) {
        if (pattern[i - 1] == '*') {

          dp[i][j] = dp[i - 1][j] || dp[i][j - 1];
        } else if (pattern[i - 1] == '?' || pattern[i - 1] == text[j - 1]) {

          dp[i][j] = dp[i - 1][j - 1];
        } else {
          dp[i][j] = false;
        }
      }
    }

    return dp[pLen][tLen];
  }

  if (args.length != 2) {
    print('Usage: dart run <script.dart> <pattern> <text>');
    return;
  }

  final String pattern = args[0];
  final String text = args[1];
  final bool isMatch = wildcardMatch(pattern, text);

  print('Pattern: "$pattern"');
  print('Text:    "$text"');
  print(isMatch ? 'Match' : 'No Match');
}

