bool candidate(String original, String corrected) {
  int asciiSum(String s) {
    int sum = 0;
    for (int i = 0; i < s.length; i++) {
      sum += s.codeUnitAt(i);
    }
    return sum;
  }

  int gcd(int a, int b) {
    while (b != 0) {
      int temp = b;
      b = a % b;
      a = temp;
    }
    return a;
  }

  bool isPrime(int n) {
    if (n <= 1) return false;
    if (n <= 3) return true;
    if (n % 2 == 0 || n % 3 == 0) return false;
    for (int i = 5; i * i <= n; i += 6) {
      if (n % i == 0 || n % (i + 2) == 0) return false;
    }
    return true;
  }

  if (original.length != corrected.length) return false;

  List<int> diff = [];
  for (int i = 0; i < original.length; i++) {
    if (original[i] != corrected[i]) diff.add(i);
  }
  if (diff.length != 2) return false;

  int sumOrig = asciiSum(original);
  int sumCorr = asciiSum(corrected);

  if (gcd(sumOrig, sumCorr) != 1) return false;

  String intermediate1 = original.substring(0, diff[0]) + corrected[diff[0]] + original.substring(diff[0] + 1);
  String intermediate2 = original.substring(0, diff[1]) + corrected[diff[1]] + original.substring(diff[1] + 1);

  return isPrime(asciiSum(intermediate1)) || isPrime(asciiSum(intermediate2));
}

