    final parts = line.split(' ');
    if (parts.length != 3) continue;
    final ts = int.tryParse(parts[0]);
    final rid = int.tryParse(parts[1]);
    final bytes = int.tryParse(parts[2]);
    if (ts == null || rid == null || bytes == null) continue;

    final bucketIndex = (ts ^ rid) & 15;
    buckets[bucketIndex].add(bytes);
