  int left = 0, right = arr.length - 1, kIndex = k - 1;
  while (true) {
    int pivot = arr[right];
    int i = left;
    for (int j = left; j < right; j++) {
      if (arr[j] <= pivot) {
        int tmp = arr[i]; arr[i] = arr[j]; arr[j] = tmp; i++;
