List<int> candidate(List<int> registeredVoters, List<List<int>> precinctVotes) {
  if (precinctVotes.isEmpty) return [];
  int candidates = precinctVotes.first.length;
  List<int> totals = List.filled(candidates, 0);
  for (int i = 0; i < precinctVotes.length; i++) {
    var votes = precinctVotes[i];
    int totalVotes = votes.fold(0, (sum, v) => sum + v);
    int seats = registeredVoters[i];
    if (totalVotes <= seats) {
      for (int j = 0; j < candidates; j++) {
        totals[j] += votes[j];
      }
    } else {
      List<int> allocated = List.filled(candidates, 0);
      List<int> remainders = List.filled(candidates, 0);
      int sumFloors = 0;
      for (int j = 0; j < candidates; j++) {
        int q = (votes[j] * seats) ~/ totalVotes;
        allocated[j] = q;
        remainders[j] = (votes[j] * seats) % totalVotes;
        sumFloors += q;
      }
      int leftover = seats - sumFloors;
      List<int> indices = List.generate(candidates, (i) => i);
      indices.sort((a, b) {
        int cmp = remainders[b].compareTo(remainders[a]);
        if (cmp != 0) return cmp;
        return a.compareTo(b);
      });
      for (int k = 0; k < leftover; k++) {
        allocated[indices[k]]++;
      }
      for (int j = 0; j < candidates; j++) {
        totals[j] += allocated[j];
      }
    }
  }
  return totals;
}

