            if (cost < nextDp[c][1]) nextDp[c][1] = cost;
          }
        }
      }
    }
    dp = nextDp;
  }

  int minCost = inf;
  for (int c = 0; c <= 1; c++) {
    for (int len = 1; len <= 2; len++) {
      if (dp[c][len] < minCost) {
