    double diffB = (moistureGrid[b] - referenceMoisture).abs();
    int cmp = diffA.compareTo(diffB);
    if (cmp != 0) return cmp;

    double distA = (rowA - centerRow).abs() + (colA - centerCol).abs();
    double distB = (rowB - centerRow).abs() + (colB - centerCol).abs();
    cmp = distA.compareTo(distB);
    if (cmp != 0) return cmp;

    cmp = rowA.compareTo(rowB);
    if (cmp != 0) return cmp;

    return colA.compareTo(colB);
  });

  return indices.map((i) {
    int row = i ~/ cols;
    int col = i % cols;
