  if (points.isEmpty || bucketSize <= 0) return 0.0;

  Map<String, List<List<int>>> buckets = {};

  for (var point in points) {
    int bx = point[0] ~/ bucketSize;
    int by = point[1] ~/ bucketSize;
    String key = '${bx},${by}';
    buckets.putIfAbsent(key, () => []).add(point);
  }

  double totalArea = 0.0;
  int bucketCount = 0;

  for (var pts in buckets.values) {
    if (pts.length < 2) continue;

    int minX = pts[0][0], maxX = pts[0][0];
    int minY = pts[0][1], maxY = pts[0][1];

    for (var p in pts) {
      if (p[0] < minX) minX = p[0];
      if (p[0] > maxX) maxX = p[0];
      if (p[1] < minY) minY = p[1];
      if (p[1] > maxY) maxY = p[1];
    }

    totalArea += (maxX - minX) * (maxY - minY);
    bucketCount++;
  }

  if (bucketCount == 0) return 0.0;
  return totalArea / bucketCount;
}

