        } else if (c == ':') {
          bucketIdx = num;
          state = AFTER_COLON;
        } else if (c == ',') {
          buckets[num] = (buckets[num] ?? 0) + 1;
          state = IDLE;
        }
        break;
      case AFTER_COLON:
        if (digit) {
          num = code - 48;
          state = READ_COUNT;
        }
