      int end = i + len - 1;
      if (cost[i][end] != inf) {
        int nextValue = dp[i] + cost[i][end];
        if (nextValue < dp[i + len]) {
          dp[i + len] = nextValue;
        }
      }
    }
  }

  return dp[n] == inf ? -1 : dp[n];
