bool candidate(String dna, int windowSize) {
  int bitForBase(String ch) {
    switch (ch) {
      case 'A':
        return 1;
      case 'C':
        return 2;
      case 'G':
        return 4;
      case 'T':
        return 8;
      default:
        return -1;
    }
