    diff[c][b]--;
    diff[a][d]--;
    diff[c][d]++;
  }

  int area = 0;
  int maxOverlap = 0;

  for (int i = 0; i < xs.length - 1; i++) {
    for (int j = 0; j < ys.length - 1; j++) {
      int v = diff[i][j];
      if (i > 0) v += diff[i - 1][j];
      if (j > 0) v += diff[i][j - 1];
      if (i > 0 && j > 0) v -= diff[i - 1][j - 1];
