      for (int j = oppStart; j < oppEnd; j++) {
        if (slots[j] != 0) {
          emptyOppSide = false;
          break;
        }
      }

      if (emptyOppSide) {
        survive = 1.0;
      }

      dp[i][round] = dp[i][round - 1] * survive;
    }
