String candidate(String tape, int scale) {
  final StringBuffer output = StringBuffer();
  int i = 0;

  while (i < tape.length) {
    int count = 0;

    while (i < tape.length) {
      int digit = tape.codeUnitAt(i) - 48;
      if (digit < 0 || digit > 9) {
        break;
      }
      count = (count * 10) + digit;
      i++;
    }

    if (count == 0) {
      count = 1;
    }

    if (i >= tape.length) {
      break;
    }

    String command = tape[i++];

    if (command == '*') {
      if (i >= tape.length) {
        break;
      }
      String ch = tape[i++];
      int repeats = count * scale;
      for (int r = 0; r < repeats; r++) {
        output.write(ch);
