    return <int>{};
  }

  bool isPrime(int value) {
    if (value < 2) {
      return false;
    }
    for (int i = 2; i * i <= value; i++) {
      if (value % i == 0) {
        return false;
      }
    }
    return true;
  }

  int gcd(int a, int b) {
    while (b != 0) {
      int temp = a % b;
      a = b;
      b = temp;
    }
    return a.abs();
  }

  Set<int> groups = <int>{};

  for (int code in shelfCodes) {
    if (code <= 0) {
      continue;
