Set<int> candidate(List<int> deck, int draws) {
  if (draws < 0 || draws > deck.length) {
    return <int>{};
  }

  Set<int> totals = <int>{};

  void search(int left, int right, int remaining, int total) {
    if (remaining == 0) {
      totals.add(total);
      return;
    }

    if (left > right) {
      return;
    }

    search(left + 1, right, remaining - 1, total + deck[left]);

    if (left != right) {
      search(left, right - 1, remaining - 1, total + deck[right]);
    }
  }

  search(0, deck.length - 1, draws, 0);
  return totals;
}

@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<String> candidate(int boardSize, List<String> queens, List<int> queries) {
  List<List<int>> queenPos = [];
  for (String q in queens) {
    int col = q.codeUnitAt(0) - 97;
    int row = int.parse(q.substring(1)) - 1;
    queenPos.add([row, col]);
  }

  List<List<int>> safeColsByRow = List.generate(boardSize, (_) => []);
  List<int> prefix = List.filled(boardSize + 1, 0);

  for (int r = 0; r < boardSize; r++) {
    for (int c = 0; c < boardSize; c++) {
      bool safe = true;
      for (List<int> q in queenPos) {
        int qr = q[0];
        int qc = q[1];
        if (r == qr || c == qc || (r - qr).abs() == (c - qc).abs()) {
          safe = false;
          break;
        }
      }
      if (safe) {
        safeColsByRow[r].add(c);
      }
    }
    prefix[r + 1] = prefix[r] + safeColsByRow[r].length;
  }

  List<String> result = [];
  for (int k in queries) {
    if (k <= 0 || k > prefix[boardSize]) {
      result.add("");
      continue;
    }

    int left = 0;
    int right = boardSize - 1;
    while (left < right) {
      int mid = (left + right) ~/ 2;
      if (prefix[mid + 1] >= k) {
        right = mid;
      } else {
        left = mid + 1;
      }
    }

    int row = left;
    int offset = k - prefix[row] - 1;
    int col = safeColsByRow[row][offset];
    result.add('${String.fromCharCode(97 + col)}${row + 1}');
  }

  return result;
}

@pragma('vm:never-inline')
@pragma('vm:entry-point')
Set<int> candidate(List<String> shelfCodes, int threshold) {
  final Set<int> indexes = <int>{};

  for (final code in shelfCodes) {
    final parts = code.split('-');
    if (parts.length != 2 || parts[0].isEmpty || parts[1].isEmpty) {
      continue;
    }

    final int letterScore = parts[0]
        .toUpperCase()
        .codeUnits
        .fold(0, (sum, unit) {
      if (unit >= 65 && unit <= 90) {
        return sum + (unit - 64);
      }
      return sum;
    });

    int digitScore = 0;
    for (final unit in parts[1].codeUnits) {
      if (unit >= 48 && unit <= 57) {
        digitScore += unit - 48;
      }
    }

    if (digitScore == 0 && letterScore < threshold) {
      continue;
    }

    final int combined = letterScore.isEven
        ? letterScore - digitScore
        : letterScore + digitScore;

    if (combined >= threshold) {
      indexes.add(combined);
    } else if (combined < 0) {
      indexes.add(-combined);
    }
  }

  return indexes;
}

