bool candidate(List<int> ingredientUnits, int targetUnits, int maxRepeatedSize) {
  if (targetUnits < 0 || maxRepeatedSize < 1) {
    return false;
  }

  Map<int, int> counts = {};
  int left = 0;
  int currentTotal = 0;

  for (int right = 0; right < ingredientUnits.length; right++) {
    int value = ingredientUnits[right];
    currentTotal += value;
    counts[value] = (counts[value] ?? 0) + 1;

    while (left <= right &&
        (currentTotal > targetUnits ||
            (counts[value] ?? 0) > maxRepeatedSize)) {
      int removed = ingredientUnits[left];
      currentTotal -= removed;
      counts[removed] = (counts[removed] ?? 0) - 1;

      if (counts[removed] == 0) {
        counts.remove(removed);
      }

      left++;
    }

    if (currentTotal == targetUnits) {
      return true;
    }
  }

  return false;
}

@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<String> candidate(List<int> waitMinutes, int expressUses) {
  int n = waitMinutes.length;
  if (n == 0) {
    return <String>[];
  }

  int limit = -1 << 30;
  List<List<List<int>>> dp = List.generate(
    n + 1,
    (_) => List.generate(expressUses + 1, (_) => List.filled(2, limit)),
  );
  List<List<List<String>>> path = List.generate(
    n + 1,
    (_) => List.generate(expressUses + 1, (_) => List.filled(2, '')),
  );

  dp[0][0][0] = 0;

  for (int i = 0; i < n; i++) {
    int saving = waitMinutes[i] < 10 ? waitMinutes[i] : 10;

    for (int used = 0; used <= expressUses; used++) {
      for (int prev = 0; prev <= 1; prev++) {
        if (dp[i][used][prev] == limit) {
          continue;
        }

        int waitScore = dp[i][used][prev];
        if (waitScore > dp[i + 1][used][0]) {
          dp[i + 1][used][0] = waitScore;
          path[i + 1][used][0] = '${path[i][used][prev]}wait,';
        }

        if (prev == 0 && used < expressUses) {
          int expressScore = dp[i][used][prev] + saving;
          if (expressScore > dp[i + 1][used + 1][1]) {
            dp[i + 1][used + 1][1] = expressScore;
            path[i + 1][used + 1][1] = '${path[i][used][prev]}express,';
          }
        }
      }
    }
  }

  int best = limit;
  String bestPath = '';

  for (int used = 0; used <= expressUses; used++) {
    for (int prev = 0; prev <= 1; prev++) {
      if (dp[n][used][prev] > best) {
        best = dp[n][used][prev];
        bestPath = path[n][used][prev];
      }
    }
  }

  return bestPath.isEmpty
      ? <String>[]
      : bestPath.substring(0, bestPath.length - 1).split(',');
}

