int candidate(List<List<String>> deckRows) {
  int matchingRows = 0;

  for (List<String> row in deckRows) {
    if (row.isEmpty) {
      continue;
    }

    String suit = row[0].substring(row[0].length - 1);
    bool allMatch = true;

    for (String card in row) {
      if (card.substring(card.length - 1) != suit) {
        allMatch = false;
        break;
      }
    }

    if (allMatch) {
      matchingRows++;
    }
  }

  return matchingRows;
}

@pragma('vm:never-inline')
@pragma('vm:entry-point')
Set<int> candidate(List<String> operations) {
  final Set<int> activeMinutes = <int>{};
  final List<String> history = <String>[];

  Set<int> shift(Set<int> source, int delta) {
    final Set<int> shifted = <int>{};
    for (final int minute in source) {
      int next = (minute + delta) % 1440;
      if (next < 0) {
        next += 1440;
      }
      shifted.add(next);
    }
    return shifted;
  }

  for (final String operation in operations) {
    final List<String> parts = operation.split(' ');
    final String type = parts[0];

    if (type == 'ADD') {
      final int minute = int.parse(parts[1]);
      if (minute >= 0 && minute < 1440 && activeMinutes.add(minute)) {
        history.add('REMOVE $minute');
      } else {
        history.add('NOP');
      }
    } else if (type == 'REMOVE') {
      final int minute = int.parse(parts[1]);
      if (activeMinutes.remove(minute)) {
        history.add('ADD $minute');
      } else {
        history.add('NOP');
      }
    } else if (type == 'SHIFT') {
      final int delta = int.parse(parts[1]);
      final Set<int> shifted = shift(activeMinutes, delta);
      activeMinutes
        ..clear()
        ..addAll(shifted);
      history.add('SHIFT ${-delta}');
    } else if (type == 'UNDO') {
      int count = int.parse(parts[1]);
      while (count > 0 && history.isNotEmpty) {
        final String inverse = history.removeLast();
        if (inverse == 'NOP') {
          count--;
          continue;
        }

        final List<String> undoParts = inverse.split(' ');
        if (undoParts[0] == 'ADD') {
          activeMinutes.add(int.parse(undoParts[1]));
        } else if (undoParts[0] == 'REMOVE') {
          activeMinutes.remove(int.parse(undoParts[1]));
        } else if (undoParts[0] == 'SHIFT') {
          final int delta = int.parse(undoParts[1]);
          final Set<int> shifted = shift(activeMinutes, delta);
          activeMinutes
            ..clear()
            ..addAll(shifted);
        }
        count--;
      }
    }
  }

  return activeMinutes;
}

@pragma('vm:never-inline')
@pragma('vm:entry-point')
Map<String, int> candidate(List<String> schedules) {
  const days = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
  final Map<String, List<List<int>>> events = {};
  final Map<String, int> result = {};

  int toMinutes(String time) {
    final parts = time.split(':');
    return int.parse(parts[0]) * 60 + int.parse(parts[1]);
  }

  void addInterval(String zone, String day, int start, int end, int temp) {
    final key = '$zone|$day';
    events.putIfAbsent(key, () => []);
    events[key]!.add([start, 1, temp]);
    events[key]!.add([end, -1, temp]);
  }

  for (final schedule in schedules) {
    final parts = schedule.split('|');
    final zone = parts[0];
    final day = parts[1];
    final range = parts[2].split('-');
    final start = toMinutes(range[0]);
    final end = toMinutes(range[1]);
    final temp = int.parse(parts[3]);
    result.putIfAbsent(zone, () => 0);

    if (end > start) {
      addInterval(zone, day, start, end, temp);
    } else {
      addInterval(zone, day, start, 1440, temp);
      final nextDay = days[(days.indexOf(day) + 1) % 7];
      addInterval(zone, nextDay, 0, end, temp);
    }
  }

  for (final entry in events.entries) {
    final zone = entry.key.split('|')[0];
    final list = entry.value;
    list.sort((a, b) {
      if (a[0] != b[0]) return a[0] - b[0];
      return a[1] - b[1];
    });

    final Map<int, int> activeTemps = {};
    int previousMinute = list[0][0];
    int index = 0;

    while (index < list.length) {
      final minute = list[index][0];
      if (activeTemps.length > 1) {
        result[zone] = result[zone]! + (minute - previousMinute);
      }

      while (index < list.length && list[index][0] == minute) {
        final delta = list[index][1];
        final temp = list[index][2];
        activeTemps[temp] = (activeTemps[temp] ?? 0) + delta;
        if (activeTemps[temp] == 0) {
          activeTemps.remove(temp);
        }
        index++;
      }

      previousMinute = minute;
    }
  }

  return result;
}

@pragma('vm:never-inline')
@pragma('vm:entry-point')
Set<int> candidate(int rows, int seatsPerRow, int base, int modulus) {
  int gcd(int a, int b) {
    while (b != 0) {
      int t = a % b;
      a = b;
      b = t;
    }
    return a.abs();
  }

  bool isPrime(int n) {
    if (n < 2) return false;
    if (n == 2) return true;
    if (n % 2 == 0) return false;
    for (int i = 3; i * i <= n; i += 2) {
      if (n % i == 0) return false;
    }
    return true;
  }

  int reversedBaseValue(int n, int radix) {
    int value = 0;
    while (n > 0) {
      value = value * radix + (n % radix);
      n ~/= radix;
    }
    return value;
  }

  Set<int> result = <int>{};
  if (rows <= 0 || seatsPerRow <= 0 || base < 2 || modulus < 1) {
    return result;
  }

  int totalSeats = rows * seatsPerRow;

  for (int seat = 1; seat <= totalSeats; seat++) {
    int mirrored = reversedBaseValue(seat, base);
    if (!isPrime(mirrored)) continue;
    if (gcd(seat, modulus) != 1) continue;

    int temp = seat;
    int digitGcd = 0;
    while (temp > 0) {
      int digit = temp % base;
      if (digit != 0) {
        digitGcd = digitGcd == 0 ? digit : gcd(digitGcd, digit);
      }
      temp ~/= base;
    }

    int row = ((seat - 1) ~/ seatsPerRow) + 1;

    if (digitGcd == 1 &&
        (mirrored + row) % modulus == seat % modulus) {
      result.add(seat);
    }
  }

  return result;
}
